-- DETECTION_DATASET CONTRACT members and their scoped AGENT_CASE copies are
-- the one narrow direct-source exception.  Every other normalized object
-- retains the complete normalization-run requirement installed by 0025/0035.
ALTER TABLE core.dataset_snapshot_members
  DROP CONSTRAINT dataset_snapshot_members_source_shape_ck;
ALTER TABLE core.dataset_snapshot_members
  ADD CONSTRAINT dataset_snapshot_members_source_shape_ck CHECK (
    (
      object_type = 'EVIDENCE_SEGMENT'
      AND evidence_segment_id IS NOT NULL
      AND evidence_segment_id = object_id
      AND response_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      object_type = 'RESPONSE'
      AND response_id IS NOT NULL
      AND response_id = object_id
      AND evidence_segment_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      snapshot_kind IN ('DETECTION_DATASET', 'AGENT_CASE')
      AND object_type = 'CONTRACT'
      AND evidence_segment_id IS NULL
      AND response_id IS NULL
      AND normalization_run_id IS NULL
      AND normalization_version IS NULL
      AND normalization_sha256 IS NULL
    )
    OR (
      object_type NOT IN ('EVIDENCE_SEGMENT', 'RESPONSE')
      AND NOT (
        snapshot_kind IN ('DETECTION_DATASET', 'AGENT_CASE')
        AND object_type = 'CONTRACT'
      )
      AND evidence_segment_id IS NULL
      AND response_id IS NULL
      AND normalization_run_id IS NOT NULL
      AND normalization_version IS NOT NULL
      AND normalization_sha256 IS NOT NULL
    )
  );

ALTER TABLE core.dataset_snapshots
  ADD COLUMN strong_identifier_fact_count bigint,
  ADD COLUMN strong_identifier_fact_set_sha256 char(64),
  ADD CONSTRAINT dataset_snapshots_strong_fact_pair_ck CHECK (
    (strong_identifier_fact_count IS NULL) =
      (strong_identifier_fact_set_sha256 IS NULL)
    AND (
      strong_identifier_fact_count IS NULL
      OR (
        strong_identifier_fact_count >= 0
        AND strong_identifier_fact_set_sha256 ~ '^[0-9a-f]{64}$'
      )
    )
  );

ALTER TABLE core.dataset_snapshot_members
  ADD CONSTRAINT dataset_snapshot_members_strong_fact_binding_uq UNIQUE (
    id, dataset_snapshot_id, member_digest, object_type, object_id,
    object_version, object_content_sha256
  );

ALTER TABLE core.supplier_identifiers
  ADD CONSTRAINT supplier_identifiers_proven_fact_binding_uq UNIQUE (
    id, supplier_id, scheme, value_hash, identifier_fact_digest,
    candidate_id, candidate_revision, candidate_digest,
    source_locator_digest, verification_evidence_digest
  );

CREATE TABLE core.dataset_snapshot_strong_identifier_facts (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  dataset_snapshot_id uuid NOT NULL,
  snapshot_member_id uuid NOT NULL,
  snapshot_member_digest char(64) NOT NULL,
  snapshot_member_object_type text NOT NULL,
  snapshot_member_object_version bigint NOT NULL,
  snapshot_member_object_content_sha256 char(64) NOT NULL,
  contract_id uuid NOT NULL,
  fact_ordinal bigint NOT NULL,
  supplier_id uuid NOT NULL,
  identifier_id uuid NOT NULL,
  scheme text NOT NULL,
  value_hash char(64) NOT NULL,
  verification_status text NOT NULL,
  proof_state text NOT NULL,
  candidate_id uuid NOT NULL,
  candidate_revision bigint NOT NULL,
  candidate_digest char(64) NOT NULL,
  source_locator_digest char(64) NOT NULL,
  verification_evidence_digest char(64) NOT NULL,
  identifier_fact_digest char(64) NOT NULL,
  fact_canonical bytea NOT NULL,
  fact_digest char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_pk PRIMARY KEY (id),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_ordinal_uq
    UNIQUE (dataset_snapshot_id, fact_ordinal),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_digest_uq
    UNIQUE (dataset_snapshot_id, fact_digest),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_identifier_uq
    UNIQUE (dataset_snapshot_id, identifier_id),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_member_fk FOREIGN KEY (
    snapshot_member_id, dataset_snapshot_id, snapshot_member_digest,
    snapshot_member_object_type, contract_id, snapshot_member_object_version,
    snapshot_member_object_content_sha256
  ) REFERENCES core.dataset_snapshot_members(
    id, dataset_snapshot_id, member_digest, object_type, object_id,
    object_version, object_content_sha256
  ) ON DELETE RESTRICT,
  CONSTRAINT dataset_snapshot_strong_identifier_facts_identifier_fk FOREIGN KEY (
    identifier_id, supplier_id, scheme, value_hash, identifier_fact_digest,
    candidate_id, candidate_revision, candidate_digest,
    source_locator_digest, verification_evidence_digest
  ) REFERENCES core.supplier_identifiers(
    id, supplier_id, scheme, value_hash, identifier_fact_digest,
    candidate_id, candidate_revision, candidate_digest,
    source_locator_digest, verification_evidence_digest
  ) ON DELETE RESTRICT,
  CONSTRAINT dataset_snapshot_strong_identifier_facts_scheme_ck CHECK (
    snapshot_member_object_type = 'CONTRACT'
    AND
    scheme IN (
      'KOREAN_BUSINESS_NUMBER', 'OPEN_DART_CORP_CODE', 'KONEPS_PARTY_KEY'
    )
  ),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_proof_ck CHECK (
    verification_status = 'VERIFIED' AND proof_state = 'PROVEN_V1'
  ),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_scalar_ck CHECK (
    fact_ordinal >= 0
    AND snapshot_member_object_version > 0
    AND candidate_revision > 0
    AND value_hash ~ '^[0-9a-f]{64}$'
    AND snapshot_member_digest ~ '^[0-9a-f]{64}$'
    AND snapshot_member_object_content_sha256 ~ '^[0-9a-f]{64}$'
    AND candidate_digest ~ '^[0-9a-f]{64}$'
    AND source_locator_digest ~ '^[0-9a-f]{64}$'
    AND verification_evidence_digest ~ '^[0-9a-f]{64}$'
    AND identifier_fact_digest ~ '^[0-9a-f]{64}$'
    AND fact_digest ~ '^[0-9a-f]{64}$'
  ),
  CONSTRAINT dataset_snapshot_strong_identifier_facts_canonical_ck CHECK (
    convert_from(fact_canonical, 'UTF8')::jsonb IS NOT NULL
    AND fact_digest = encode(
      extensions.digest(fact_canonical, 'sha256'), 'hex'
    )
  )
);
ALTER TABLE core.dataset_snapshot_strong_identifier_facts
  OWNER TO gurine_migrator;
REVOKE ALL ON core.dataset_snapshot_strong_identifier_facts FROM PUBLIC;
GRANT SELECT ON core.dataset_snapshot_strong_identifier_facts
  TO gurine_analysis_worker, gurine_control_api, gurine_auditor;
CREATE TRIGGER dataset_snapshot_strong_identifier_facts_immutable_guard
  BEFORE UPDATE OR DELETE
  ON core.dataset_snapshot_strong_identifier_facts
  FOR EACH ROW EXECUTE FUNCTION ops.reject_mutation();

-- PENDING_HUMAN identity proposals preserve the original candidate relation
-- and key while adding a closed, insert-only proposal shape.
ALTER TABLE core.supplier_identity_candidates
  ADD COLUMN proposal_state text,
  ADD COLUMN proposed_supplier_id uuid,
  ADD COLUMN matched_identifier_id uuid,
  ADD COLUMN matched_identifier_fact_digest char(64),
  ADD COLUMN match_score_basis_points integer,
  ADD COLUMN suggested_at timestamptz,
  ADD COLUMN proposal_request_sha256 char(64),
  ADD CONSTRAINT supplier_candidate_proposed_supplier_fk
    FOREIGN KEY (proposed_supplier_id)
    REFERENCES core.suppliers(id) ON DELETE RESTRICT,
  ADD CONSTRAINT supplier_candidate_matched_identifier_fk
    FOREIGN KEY (matched_identifier_id)
    REFERENCES core.supplier_identifiers(id) ON DELETE RESTRICT,
  ADD CONSTRAINT supplier_candidate_proposal_request_uq
    UNIQUE (proposal_request_sha256),
  ADD CONSTRAINT supplier_candidate_proposal_shape_ck CHECK (
    (
      proposal_state IS NULL
      AND num_nonnulls(
        proposed_supplier_id, matched_identifier_id,
        matched_identifier_fact_digest, match_score_basis_points,
        suggested_at, proposal_request_sha256
      ) = 0
    )
    OR (
      proposal_state = 'PENDING_HUMAN'
      AND candidate_revision = 1
      AND predecessor_candidate_revision IS NULL
      AND predecessor_candidate_digest IS NULL
      AND identity_status = 'CANDIDATE'
      AND canonical_supplier_id IS NULL
      AND resolution_decision_id IS NULL
      AND resolution_decision_digest IS NULL
      AND num_nonnulls(
        proposed_supplier_id, matched_identifier_id,
        matched_identifier_fact_digest, match_score_basis_points,
        suggested_at, proposal_request_sha256
      ) = 6
      AND matched_identifier_fact_digest ~ '^[0-9a-f]{64}$'
      AND proposal_request_sha256 ~ '^[0-9a-f]{64}$'
      AND match_score_basis_points = 10000
    )
  );

-- UUID actor rows remain valid.  New automated run-control receipts use an
-- explicit SERVICE / analysis-worker textual identity instead of a fake UUID.
ALTER TABLE ops.agent_run_control_receipts
  ADD COLUMN actor_type text,
  ADD COLUMN actor_id_text text,
  ADD COLUMN worker_job_id uuid,
  ADD COLUMN worker_lease_token uuid,
  ADD COLUMN worker_fencing_token bigint,
  ADD CONSTRAINT agent_run_control_receipts_worker_job_fk
    FOREIGN KEY (worker_job_id) REFERENCES ops.jobs(id) ON DELETE RESTRICT,
  ADD CONSTRAINT agent_run_control_receipts_worker_shape_ck CHECK (
    (
      actor_type IS NULL
      AND num_nonnulls(
        worker_job_id, worker_lease_token, worker_fencing_token
      ) = 0
    )
    OR (
      actor_type = 'SERVICE'
      AND actor_kind = 'ANALYSIS_WORKER'
      AND num_nonnulls(
        worker_job_id, worker_lease_token, worker_fencing_token
      ) = 3
      AND worker_fencing_token > 0
    )
  );
ALTER TABLE ops.agent_run_control_receipts
  DROP CONSTRAINT agent_run_control_receipts_actor_ck;
ALTER TABLE ops.agent_run_control_receipts
  ADD CONSTRAINT agent_run_control_receipts_actor_ck CHECK (
    (
      actor_type IS NULL
      AND actor_id_text IS NULL
      AND (
        (actor_kind = 'SCHEDULER' AND actor_id IS NULL)
        OR (actor_kind <> 'SCHEDULER' AND actor_id IS NOT NULL)
      )
    )
    OR (
      actor_type = 'SERVICE'
      AND actor_kind = 'ANALYSIS_WORKER'
      AND actor_id IS NULL
      AND actor_id_text = 'analysis-worker'
    )
  );
ALTER TABLE ops.agent_run_control_receipts
  DROP CONSTRAINT agent_run_control_receipts_safe_retry_ck;
ALTER TABLE ops.agent_run_control_receipts
  ADD CONSTRAINT agent_run_control_receipts_safe_retry_ck CHECK (
    NOT (
      prior_control_state = 'CANCEL_REQUESTED'
      AND next_control_state = 'ACTIVE'
    )
    AND (
      next_control_state <> 'ACTIVE'
      OR (
        aggregate_version = 1
        AND prior_control_state IS NULL
        AND reason_code = 'RUN_STARTED'
      )
      OR (
        prior_control_state = 'RECONCILIATION_REQUIRED'
        AND reason_code = 'SAFE_RETRY_AUTHORIZED'
      )
      OR (
        prior_control_state = 'ACTIVE'
        AND reason_code = 'TURN_ADVANCED'
      )
    )
  );
ALTER TABLE ops.agent_run_control_receipts
  ADD CONSTRAINT agent_run_control_receipts_run_fk
    FOREIGN KEY (agent_run_id)
    REFERENCES ops.agent_runs(id) ON DELETE RESTRICT,
  ADD CONSTRAINT agent_run_control_receipts_audit_fk
    FOREIGN KEY (audit_event_id)
    REFERENCES ops.audit_events(id) ON DELETE RESTRICT;

ALTER TABLE ops.signal_investigation_policies
  ADD COLUMN retention_schedule_id uuid,
