  ADD COLUMN retention_schedule_digest char(64),
  ADD CONSTRAINT signal_investigation_policies_retention_class_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_POLICY'
  ),
