  ) MATCH FULL ON DELETE RESTRICT;

ALTER TABLE ops.signal_investigation_initiation_receipts
  ADD COLUMN retention_schedule_id uuid,
  ADD COLUMN retention_record_class text,
  ADD COLUMN retention_schedule_digest char(64),
  ADD CONSTRAINT signal_investigation_receipts_retention_class_ck CHECK (
    retention_record_class IS NULL
    OR retention_record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
  ),
  ADD CONSTRAINT signal_investigation_receipts_retention_fk FOREIGN KEY (
    retention_schedule_id, retention_record_class, retention_schedule_digest
  ) REFERENCES ops.record_class_schedules(
    id, record_class, schedule_digest
  ) MATCH FULL ON DELETE RESTRICT;

-- New events are inserted with their exact payload schemas before any owner
-- routine can enqueue them.
DO $new_event_registry$
DECLARE
  v_inserted integer;
BEGIN
INSERT INTO ops.event_types(
  event_type, category, schema_version, active, payload_schema_uri,
  payload_schema
) VALUES
(
  'normalization.run_completed.v1', 'DOMAIN', 1, true,
  'payloads/normalization_run_completed_v1.schema.json',
  '{
    "additionalProperties": false,
    "type": "object",
    "properties": {
      "normalizationRunId": {"format":"uuid","type":"string"},
      "state": {"enum":["SUCCEEDED","FAILED"],"type":"string"},
      "aggregateVersion": {"minimum":2,"type":"integer"},
      "outputObjectType": {"type":["string","null"]},
      "outputObjectId": {"format":"uuid","type":["string","null"]},
      "outputObjectVersion": {"minimum":1,"type":["integer","null"]},
      "outputPayloadSha256": {"pattern":"^[0-9a-f]{64}$","type":["string","null"]},
      "fieldProvenanceCount": {"minimum":0,"type":"integer"},
      "fieldProvenanceSetSha256": {"pattern":"^[0-9a-f]{64}$","type":["string","null"]},
      "errorCode": {"pattern":"^[A-Z][A-Z0-9_]{0,127}$","type":["string","null"]},
      "errorSha256": {"pattern":"^[0-9a-f]{64}$","type":["string","null"]},
      "terminalReceiptSha256": {"pattern":"^[0-9a-f]{64}$","type":"string"},
      "auditEventId": {"format":"uuid","type":"string"},
      "occurredAt": {"format":"date-time","type":"string"}
    },
    "required": [
      "normalizationRunId","state","aggregateVersion",
      "outputObjectType","outputObjectId","outputObjectVersion",
      "outputPayloadSha256","fieldProvenanceCount",
      "fieldProvenanceSetSha256","errorCode","errorSha256",
      "terminalReceiptSha256","auditEventId","occurredAt"
    ]
  }'::jsonb
);
GET DIAGNOSTICS v_inserted = ROW_COUNT;
IF v_inserted <> 1 THEN
  RAISE EXCEPTION
    'new event registry cardinality mismatch: expected %, inserted %',
    1,v_inserted USING ERRCODE = '55000';
END IF;
END
$new_event_registry$;

CREATE OR REPLACE FUNCTION ops.bind_r6b_runtime_retention_schedule_v1()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, pg_temp
AS $$
DECLARE
  v_class text;
  v_match_count bigint;
  v_schedule ops.record_class_schedules%ROWTYPE;
BEGIN
  v_class := CASE TG_TABLE_NAME
    WHEN 'signal_investigation_policies' THEN 'AGENT_RUNTIME_POLICY'
    WHEN 'signal_investigation_initiation_receipts'
      THEN 'AGENT_RUNTIME_INITIATION_RECEIPT'
    ELSE NULL
  END;
  IF v_class IS NULL THEN
    RAISE EXCEPTION 'r6b_runtime_retention_relation_invalid'
      USING ERRCODE = '55000';
  END IF;

  IF num_nonnulls(
    NEW.retention_schedule_id, NEW.retention_record_class,
    NEW.retention_schedule_digest
  ) <> 0 THEN
    RAISE EXCEPTION 'r6b_runtime_retention_binding_override_forbidden'
      USING ERRCODE = '23514';
  END IF;
  LOCK TABLE ops.record_class_schedules IN SHARE MODE;
  SELECT count(*) INTO v_match_count
  FROM ops.record_class_schedules AS schedule
  WHERE schedule.record_class = v_class
    AND schedule.effective_at <= NEW.created_at
    AND schedule.review_expires_at > NEW.created_at
    AND schedule.active_duration_seconds IS NOT NULL
    AND schedule.backup_duration_seconds IS NOT NULL
    AND schedule.terminal_action IN ('DELETE','ANONYMIZE','CRYPTO_ERASE');
  IF v_match_count = 0 THEN
    RAISE EXCEPTION 'r6b_runtime_retention_schedule_missing'
      USING ERRCODE = '55000';
  ELSIF v_match_count <> 1 THEN
    RAISE EXCEPTION 'r6b_runtime_retention_schedule_ambiguous'
      USING ERRCODE = '55000';
  END IF;
  SELECT schedule.* INTO v_schedule
  FROM ops.record_class_schedules AS schedule
  WHERE schedule.record_class = v_class
    AND schedule.effective_at <= NEW.created_at
    AND schedule.review_expires_at > NEW.created_at
    AND schedule.active_duration_seconds IS NOT NULL
    AND schedule.backup_duration_seconds IS NOT NULL
    AND schedule.terminal_action IN ('DELETE','ANONYMIZE','CRYPTO_ERASE')
  ORDER BY schedule.revision DESC, schedule.effective_at DESC, schedule.id
  LIMIT 1
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'r6b_runtime_retention_schedule_missing'
      USING ERRCODE = '55000';
  END IF;

  NEW.retention_schedule_id := v_schedule.id;
  NEW.retention_record_class := v_schedule.record_class;
  NEW.retention_schedule_digest := v_schedule.schedule_digest;
  RETURN NEW;
END
$$;
ALTER FUNCTION ops.bind_r6b_runtime_retention_schedule_v1()
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.bind_r6b_runtime_retention_schedule_v1()
  FROM PUBLIC;

-- Backfill is performed with only the two immutable guards suspended inside
-- this migration.  They are re-enabled before the columns become mandatory.
DO $$
DECLARE
  v_bad_policy_count bigint;
  v_bad_receipt_count bigint;
BEGIN
  LOCK TABLE ops.record_class_schedules IN SHARE MODE;
  SELECT count(*) INTO v_bad_policy_count
  FROM ops.signal_investigation_policies AS policy
  WHERE (
    SELECT count(*) FROM ops.record_class_schedules AS schedule
    WHERE schedule.record_class = 'AGENT_RUNTIME_POLICY'
      AND schedule.effective_at <= policy.created_at
      AND schedule.review_expires_at > policy.created_at
      AND schedule.active_duration_seconds IS NOT NULL
      AND schedule.backup_duration_seconds IS NOT NULL
      AND schedule.terminal_action IN ('DELETE','ANONYMIZE','CRYPTO_ERASE')
  ) <> 1;
  SELECT count(*) INTO v_bad_receipt_count
  FROM ops.signal_investigation_initiation_receipts AS receipt
  WHERE (
    SELECT count(*) FROM ops.record_class_schedules AS schedule
    WHERE schedule.record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
      AND schedule.effective_at <= receipt.created_at
      AND schedule.review_expires_at > receipt.created_at
      AND schedule.active_duration_seconds IS NOT NULL
      AND schedule.backup_duration_seconds IS NOT NULL
      AND schedule.terminal_action IN ('DELETE','ANONYMIZE','CRYPTO_ERASE')
  ) <> 1;
  IF v_bad_policy_count <> 0 OR v_bad_receipt_count <> 0 THEN
    RAISE EXCEPTION
      'r6b_runtime_retention_backfill_authority_missing_or_ambiguous'
      USING ERRCODE = '55000';
  END IF;
END;
$$;

ALTER TABLE ops.signal_investigation_policies
  DISABLE TRIGGER signal_investigation_policies_immutable_guard;
UPDATE ops.signal_investigation_policies AS policy
SET (retention_schedule_id, retention_record_class,
     retention_schedule_digest) = (
  SELECT schedule.id, schedule.record_class, schedule.schedule_digest
  FROM ops.record_class_schedules AS schedule
  WHERE schedule.record_class = 'AGENT_RUNTIME_POLICY'
    AND schedule.effective_at <= policy.created_at
    AND schedule.review_expires_at > policy.created_at
    AND schedule.active_duration_seconds IS NOT NULL
    AND schedule.backup_duration_seconds IS NOT NULL
    AND schedule.terminal_action IN ('DELETE','ANONYMIZE','CRYPTO_ERASE')
  ORDER BY schedule.effective_at DESC, schedule.revision DESC, schedule.id DESC
  LIMIT 1
);
ALTER TABLE ops.signal_investigation_policies
  ENABLE TRIGGER signal_investigation_policies_immutable_guard;

ALTER TABLE ops.signal_investigation_initiation_receipts
  DISABLE TRIGGER signal_investigation_receipts_immutable_guard;
UPDATE ops.signal_investigation_initiation_receipts AS receipt
SET (retention_schedule_id, retention_record_class,
     retention_schedule_digest) = (
  SELECT schedule.id, schedule.record_class, schedule.schedule_digest
  FROM ops.record_class_schedules AS schedule
  WHERE schedule.record_class = 'AGENT_RUNTIME_INITIATION_RECEIPT'
    AND schedule.effective_at <= receipt.created_at
    AND schedule.review_expires_at > receipt.created_at
    AND schedule.active_duration_seconds IS NOT NULL
    AND schedule.backup_duration_seconds IS NOT NULL
    AND schedule.terminal_action IN ('DELETE','ANONYMIZE','CRYPTO_ERASE')
  ORDER BY schedule.effective_at DESC, schedule.revision DESC, schedule.id DESC
  LIMIT 1
);
ALTER TABLE ops.signal_investigation_initiation_receipts
  ENABLE TRIGGER signal_investigation_receipts_immutable_guard;

ALTER TABLE ops.signal_investigation_policies
  ALTER COLUMN retention_schedule_id SET NOT NULL,
  ALTER COLUMN retention_record_class SET NOT NULL,
  ALTER COLUMN retention_schedule_digest SET NOT NULL;
ALTER TABLE ops.signal_investigation_initiation_receipts
  ALTER COLUMN retention_schedule_id SET NOT NULL,
  ALTER COLUMN retention_record_class SET NOT NULL,
  ALTER COLUMN retention_schedule_digest SET NOT NULL;

CREATE TRIGGER signal_investigation_policies_retention_binding_guard
  BEFORE INSERT ON ops.signal_investigation_policies
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6b_runtime_retention_schedule_v1();
CREATE TRIGGER signal_investigation_receipts_retention_binding_guard
  BEFORE INSERT ON ops.signal_investigation_initiation_receipts
  FOR EACH ROW EXECUTE FUNCTION ops.bind_r6b_runtime_retention_schedule_v1();

CREATE OR REPLACE FUNCTION core.record_supplier_identity_candidate_v1(
  p_request jsonb
) RETURNS TABLE(
  candidate_id uuid,
  merge_decision_id uuid,
  disposition text,
  recorded boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_source raw.source_documents%ROWTYPE;
  v_record raw.parsed_records%ROWTYPE;
  v_identifier core.supplier_identifiers%ROWTYPE;
  v_existing core.supplier_identity_candidates%ROWTYPE;
  v_candidate_id uuid := gen_random_uuid();
  v_source_document_id uuid;
  v_parsed_record_id uuid;
  v_target_supplier_id uuid;
  v_record_index integer;
  v_normalized_name text;
  v_scheme text;
  v_value_hmac char(64);
  v_identifier_fact_digest char(64);
  v_score integer;
  v_name_locator jsonb;
  v_name_locator_digest char(64);
  v_payload jsonb;
  v_canonical bytea;
  v_candidate_digest char(64);
  v_request_sha256 char(64);
  v_suggested_at timestamptz := clock_timestamp();
BEGIN
  IF p_request IS NULL
     OR jsonb_typeof(p_request) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'supplier_candidate_request_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_request)) <> 10
     OR jsonb_typeof(p_request->'schemaVersion') IS DISTINCT FROM 'string'
     OR p_request->>'schemaVersion' IS DISTINCT FROM
       'supplier-identity-candidate-proposal.request.v1'
     OR NOT p_request ?& ARRAY[
       'schemaVersion','sourceDocumentId','parsedRecordId','recordIndex',
       'normalizedName','observedScheme','observedValueHmac',
       'targetSupplierId','identifierFactDigest','scoreBasisPoints'
     ]
     OR jsonb_typeof(p_request->'sourceDocumentId')
       IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'parsedRecordId') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'recordIndex') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_request->'normalizedName') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'observedScheme') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'observedValueHmac')
       IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'targetSupplierId')
       IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'identifierFactDigest')
       IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_request->'scoreBasisPoints')
       IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'supplier_candidate_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_source_document_id := (p_request->>'sourceDocumentId')::uuid;
    v_parsed_record_id := (p_request->>'parsedRecordId')::uuid;
    v_target_supplier_id := (p_request->>'targetSupplierId')::uuid;
    v_record_index := (p_request->>'recordIndex')::integer;
    v_score := (p_request->>'scoreBasisPoints')::integer;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'supplier_candidate_request_invalid'
      USING ERRCODE = '22023';
  END;
  v_normalized_name := nullif(btrim(p_request->>'normalizedName'), '');
  v_scheme := p_request->>'observedScheme';
  v_value_hmac := p_request->>'observedValueHmac';
  v_identifier_fact_digest := p_request->>'identifierFactDigest';
  IF v_record_index IS NULL OR v_record_index < 0
     OR v_normalized_name IS NULL OR v_score IS DISTINCT FROM 10000
     OR v_scheme NOT IN (
       'KOREAN_BUSINESS_NUMBER','OPEN_DART_CORP_CODE','KONEPS_PARTY_KEY'
     )
     OR COALESCE(v_value_hmac,'') !~ '^[0-9a-f]{64}$'
     OR COALESCE(v_identifier_fact_digest,'') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'supplier_candidate_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT document.* INTO v_source
  FROM raw.source_documents AS document
  WHERE document.id = v_source_document_id
  FOR SHARE;
  SELECT record.* INTO v_record
  FROM raw.parsed_records AS record
  WHERE record.id = v_parsed_record_id
    AND record.source_document_id = v_source_document_id
    AND record.record_index = v_record_index
  FOR SHARE;
  IF v_source.id IS NULL OR v_record.id IS NULL THEN
    RAISE EXCEPTION 'supplier_candidate_source_binding_invalid'
      USING ERRCODE = '23503';
  END IF;

  SELECT identifier.* INTO v_identifier
  FROM core.supplier_identifiers AS identifier
  WHERE identifier.supplier_id = v_target_supplier_id
    AND identifier.scheme = v_scheme
    AND identifier.value_hash = v_value_hmac
    AND identifier.identifier_fact_digest = v_identifier_fact_digest
    AND identifier.verification_status = 'VERIFIED'
    AND identifier.proof_state = 'PROVEN_V1'
    AND identifier.candidate_id IS NOT NULL
    AND identifier.candidate_revision IS NOT NULL
    AND identifier.candidate_digest IS NOT NULL
    AND identifier.source_locator_digest IS NOT NULL
    AND identifier.verification_evidence_digest IS NOT NULL
  FOR SHARE;
  IF v_identifier.id IS NULL THEN
    RAISE EXCEPTION 'supplier_candidate_strong_fact_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_request_sha256 := encode(
    extensions.digest(ops.canonical_jsonb_v1(p_request), 'sha256'), 'hex'
  );
  SELECT candidate.* INTO v_existing
  FROM core.supplier_identity_candidates AS candidate
  WHERE candidate.source_document_id = v_source_document_id
    AND candidate.parsed_record_id = v_parsed_record_id
    AND candidate.record_index = v_record_index
    AND candidate.mapping_version = v_record.parser_version
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.proposal_state = 'PENDING_HUMAN'
       AND v_existing.proposal_request_sha256 = v_request_sha256
       AND v_existing.proposed_supplier_id = v_target_supplier_id
       AND v_existing.matched_identifier_id = v_identifier.id
       AND v_existing.matched_identifier_fact_digest =
         v_identifier.identifier_fact_digest
       AND v_existing.match_score_basis_points = 10000 THEN
      RETURN QUERY SELECT v_existing.candidate_id, NULL::uuid,
        'PENDING_HUMAN'::text, true;
      RETURN;
    END IF;
    RAISE EXCEPTION 'supplier_candidate_replay_conflict'
      USING ERRCODE = '40001';
  END IF;

  v_name_locator := jsonb_build_object(
    'sourceDocumentId', v_source_document_id,
    'parsedRecordId', v_parsed_record_id,
    'recordIndex', v_record_index,
    'field', 'normalizedName'
  );
  v_name_locator_digest := encode(
    extensions.digest(ops.canonical_jsonb_v1(v_name_locator), 'sha256'),
    'hex'
  );
  v_payload := jsonb_build_object(
    'schemaVersion', 'supplier-identity-candidate-proposal.v1',
    'candidateId', v_candidate_id,
    'candidateRevision', 1,
    'sourceDocumentId', v_source_document_id,
    'parsedRecordId', v_parsed_record_id,
    'sourceRecordDigest', btrim(v_record.payload_sha256),
    'recordIndex', v_record_index,
    'mappingVersion', v_record.parser_version,
    'normalizedName', v_normalized_name,
    'nameSourceLocatorDigest', btrim(v_name_locator_digest),
    'proposedSupplierId', v_target_supplier_id,
    'identifierId', v_identifier.id,
    'identifierScheme', v_identifier.scheme,
    'identifierValueHmac', btrim(v_identifier.value_hash),
    'identifierFactDigest', btrim(v_identifier.identifier_fact_digest),
    'scoreBasisPoints', 10000,
    'suggestedAt', to_char(
      v_suggested_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    ),
    'proposalState', 'PENDING_HUMAN'
  );
  v_canonical := ops.canonical_jsonb_v1(v_payload);
  v_candidate_digest := encode(
    extensions.digest(v_canonical, 'sha256'), 'hex'
  );

  INSERT INTO core.supplier_identity_candidates(
    candidate_id, candidate_revision, candidate_digest,
    predecessor_candidate_revision, predecessor_candidate_digest,
    source_document_id, source_asset_id, source_asset_revision,
    source_content_sha256, parsed_record_id, source_record_digest,
    record_index, mapping_version, normalized_name,
    name_source_locator_digest, identifier_count, identifier_set_digest,
    identity_status, canonical_supplier_id, resolution_decision_id,
    resolution_decision_digest, candidate_payload, candidate_canonical,
    candidate_digest_preimage_canonical, created_at, proposal_state,
    proposed_supplier_id, matched_identifier_id,
    matched_identifier_fact_digest, match_score_basis_points,
    suggested_at, proposal_request_sha256
  ) VALUES (
    v_candidate_id, 1, v_candidate_digest, NULL, NULL,
    v_source.id, v_source.asset_id, v_source.asset_revision,
    v_source.content_sha256, v_record.id, v_record.payload_sha256,
    v_record_index, v_record.parser_version, v_normalized_name,
    v_name_locator_digest, 1, v_identifier.identifier_fact_digest,
    'CANDIDATE', NULL, NULL, NULL, v_payload, v_canonical, v_canonical,
    v_suggested_at, 'PENDING_HUMAN', v_target_supplier_id,
    v_identifier.id, v_identifier.identifier_fact_digest, 10000,
    v_suggested_at, v_request_sha256
  );
  RETURN QUERY SELECT v_candidate_id, NULL::uuid,
    'PENDING_HUMAN'::text, true;
END
$$;
GRANT SELECT ON raw.parsed_records, core.supplier_identifiers
  TO gurine_migrator;
GRANT UPDATE (id) ON raw.parsed_records, core.supplier_identifiers
  TO gurine_migrator;
ALTER FUNCTION core.record_supplier_identity_candidate_v1(jsonb)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.record_supplier_identity_candidate_v1(jsonb)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.record_supplier_identity_candidate_v1(jsonb)
  TO gurine_ingest_worker;

CREATE OR REPLACE FUNCTION ops.append_analysis_run_control_receipt_v2(
  p_agent_run_id uuid,
  p_aggregate_version bigint,
  p_prior_status text,
  p_prior_control_state text,
  p_next_status text,
  p_next_control_state text,
  p_proof_kind text,
  p_proof_sha256 char(64),
  p_budget_disposition text,
  p_budget_resolution_set_sha256 char(64),
  p_reason_code text,
  p_reason_sha256 char(64),
  p_prior_receipt_id uuid,
  p_prior_receipt_sha256 char(64),
  p_worker_job_id uuid,
  p_worker_lease_token uuid,
  p_worker_fencing_token bigint,
  p_occurred_at timestamptz
) RETURNS TABLE(
  receipt_id uuid,
  receipt_sha256 char(64),
  audit_event_id uuid,
  outbox_event_id uuid
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, extensions, pg_temp
AS $$
DECLARE
  v_receipt_id uuid := gen_random_uuid();
  v_audit_event_id uuid;
  v_outbox_event_id uuid;
  v_lease_token_sha256 char(64);
  v_audit_details jsonb;
  v_receipt_preimage jsonb;
  v_receipt_canonical bytea;
  v_receipt_sha256 char(64);
  v_event_payload jsonb;
BEGIN
  IF p_agent_run_id IS NULL OR p_aggregate_version < 1
     OR p_worker_job_id IS NULL OR p_worker_lease_token IS NULL
     OR p_worker_fencing_token < 1 OR p_occurred_at IS NULL
     OR p_proof_sha256 !~ '^[0-9a-f]{64}$'
     OR p_budget_resolution_set_sha256 !~ '^[0-9a-f]{64}$'
     OR p_reason_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'analysis_run_control_receipt_invalid'
      USING ERRCODE = '22023';
  END IF;
  v_lease_token_sha256 := encode(
    extensions.digest(convert_to(p_worker_lease_token::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_audit_details := jsonb_build_object(
    'runId', p_agent_run_id,
    'aggregateVersion', p_aggregate_version,
    'priorStatus', p_prior_status,
    'priorControlState', p_prior_control_state,
    'nextStatus', p_next_status,
    'nextControlState', p_next_control_state,
    'proofKind', p_proof_kind,
    'proofSha256', btrim(p_proof_sha256),
    'reasonCode', p_reason_code,
    'reasonSha256', btrim(p_reason_sha256),
    'workerJobId', p_worker_job_id,
    'workerLeaseTokenSha256', btrim(v_lease_token_sha256),
    'workerFencingToken', p_worker_fencing_token,
    'occurredAt', to_char(
      p_occurred_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  v_audit_event_id := ops.append_audit_event(
    'agent-run:' || p_agent_run_id::text,
    'SERVICE', 'analysis-worker', NULL,
    CASE p_reason_code
      WHEN 'RUN_STARTED' THEN 'AGENT_RUN_STARTED'
      WHEN 'OUTCOME_AMBIGUOUS' THEN 'AGENT_RUN_RECONCILIATION_REQUIRED'
      ELSE 'AGENT_RUN_TERMINAL'
    END,
    'AgentRun', p_agent_run_id::text, 'jobs.operate', 'SUCCESS', NULL,
    p_worker_job_id, v_audit_details
  );
  v_receipt_preimage := jsonb_build_object(
    'schemaVersion', 'agent-run-control-receipt.v2',
    'receiptId', v_receipt_id,
    'runId', p_agent_run_id,
    'aggregateVersion', p_aggregate_version,
    'priorStatus', p_prior_status,
    'priorControlState', p_prior_control_state,
    'nextStatus', p_next_status,
    'nextControlState', p_next_control_state,
    'affectedProviderTurnId', NULL,
    'affectedToolCallId', NULL,
    'reconciliationEvidenceId', NULL,
    'reconciliationEvidenceSha256', NULL,
    'proofKind', p_proof_kind,
    'proofSha256', btrim(p_proof_sha256),
    'budgetDisposition', p_budget_disposition,
    'budgetResolutionSetSha256', btrim(p_budget_resolution_set_sha256),
    'actorType', 'SERVICE',
    'actorKind', 'ANALYSIS_WORKER',
    'actorId', 'analysis-worker',
    'reasonCode', p_reason_code,
    'reasonSha256', btrim(p_reason_sha256),
    'priorReceiptId', p_prior_receipt_id,
    'priorReceiptSha256', CASE
      WHEN p_prior_receipt_sha256 IS NULL THEN NULL
      ELSE btrim(p_prior_receipt_sha256)
    END,
    'commandBinding', NULL,
    'auditEventId', v_audit_event_id,
    'workerJobId', p_worker_job_id,
    'workerLeaseTokenSha256', btrim(v_lease_token_sha256),
    'workerFencingToken', p_worker_fencing_token,
    'occurredAt', to_char(
      p_occurred_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt_preimage);
  v_receipt_sha256 := encode(
    extensions.digest(v_receipt_canonical, 'sha256'), 'hex'
  );
  INSERT INTO ops.agent_run_control_receipts(
    receipt_id, receipt_contract_version, agent_run_id, aggregate_version,
    prior_status, prior_control_state, next_status, next_control_state,
    affected_provider_turn_id, affected_tool_call_id,
    reconciliation_evidence_id, reconciliation_evidence_sha256,
    proof_kind, proof_sha256, budget_disposition,
    budget_resolution_set_sha256, actor_kind, actor_id, actor_type,
    actor_id_text, reason_code, reason_sha256, command_operation_id,
    command_expected_run_version, command_idempotency_key_sha256,
    command_request_sha256, prior_receipt_id, prior_receipt_sha256,
    audit_event_id, occurred_at, receipt_canonical, receipt_sha256,
    worker_job_id, worker_lease_token, worker_fencing_token, created_at
  ) VALUES (
    v_receipt_id, 2, p_agent_run_id, p_aggregate_version,
    p_prior_status, p_prior_control_state, p_next_status,
    p_next_control_state, NULL, NULL, NULL, NULL, p_proof_kind,
    p_proof_sha256, p_budget_disposition, p_budget_resolution_set_sha256,
    'ANALYSIS_WORKER', NULL, 'SERVICE', 'analysis-worker', p_reason_code,
    p_reason_sha256, NULL, NULL, NULL, NULL, p_prior_receipt_id,
    p_prior_receipt_sha256, v_audit_event_id, p_occurred_at,
    v_receipt_canonical, v_receipt_sha256, p_worker_job_id,
    p_worker_lease_token, p_worker_fencing_token, p_occurred_at
  );
  v_event_payload := jsonb_build_object(
    'runId', p_agent_run_id,
    'aggregateVersion', p_aggregate_version,
    'priorStatus', p_prior_status,
    'priorControlState', p_prior_control_state,
    'nextStatus', p_next_status,
    'nextControlState', p_next_control_state,
    'affectedProviderTurnId', NULL,
    'affectedToolCallId', NULL,
    'reconciliationEvidenceId', NULL,
    'reconciliationEvidenceSha256', NULL,
    'proofKind', p_proof_kind,
    'proofSha256', btrim(p_proof_sha256),
    'budgetDisposition', p_budget_disposition,
    'budgetResolutionSetSha256', btrim(p_budget_resolution_set_sha256),
    'actorType', 'SERVICE',
    'actorKind', 'ANALYSIS_WORKER',
    'actorId', 'analysis-worker',
    'reasonCode', p_reason_code,
    'reasonSha256', btrim(p_reason_sha256),
    'occurredAt', to_char(
      p_occurred_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    ),
    'receiptSha256', btrim(v_receipt_sha256)
  );
  v_outbox_event_id := ops.enqueue_outbox(
    'agent_run', p_agent_run_id::text, p_aggregate_version,
    'agent.run_control_changed.v2', v_event_payload, p_occurred_at
  );
  RETURN QUERY SELECT v_receipt_id, v_receipt_sha256,
    v_audit_event_id, v_outbox_event_id;
END
$$;
ALTER FUNCTION ops.append_analysis_run_control_receipt_v2(
  uuid,bigint,text,text,text,text,text,char(64),text,char(64),text,char(64),
  uuid,char(64),uuid,uuid,bigint,timestamptz
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.append_analysis_run_control_receipt_v2(
  uuid,bigint,text,text,text,text,text,char(64),text,char(64),text,char(64),
  uuid,char(64),uuid,uuid,bigint,timestamptz
) FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.claim_agent_run_worker_v2(
  p_agent_run_id uuid,
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint
) RETURNS TABLE(
  case_id uuid,
  agent_type text,
  objective text,
  evidence_scope_ids jsonb,
  input_snapshot_hash char(64),
  max_cost numeric,
  version bigint,
  run_contract_version smallint,
  dataset_snapshot_id uuid,
  claim_receipt_id uuid,
  claim_receipt_sha256 char(64)
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_run ops.agent_runs%ROWTYPE;
  v_job ops.jobs%ROWTYPE;
  v_head ops.agent_run_control_receipts%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_proof jsonb;
  v_proof_sha256 char(64);
  v_budget_set_sha256 char(64);
  v_receipt_id uuid;
  v_receipt_sha256 char(64);
  v_unused_audit uuid;
  v_unused_outbox uuid;
BEGIN
  IF p_agent_run_id IS NULL OR p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token < 1 THEN
    RAISE EXCEPTION 'agent_run_claim_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT run.* INTO v_run
  FROM ops.agent_runs AS run
  WHERE run.id = p_agent_run_id
  FOR UPDATE;
  IF NOT FOUND OR v_run.run_contract_version <> 2 THEN
    RAISE EXCEPTION 'agent_run_v2_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id
    AND job.job_type = 'AGENT_RUN'
    AND job.queue = 'analysis-worker'
    AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > v_now
    AND job.payload->>'agentRunId' = p_agent_run_id::text
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_job_fence_stale' USING ERRCODE = '40001';
  END IF;

  IF v_run.status = 'RUNNING' AND v_run.control_state = 'ACTIVE' THEN
    SELECT receipt.* INTO v_head
    FROM ops.agent_run_control_receipts AS receipt
    WHERE receipt.agent_run_id = v_run.id
      AND receipt.aggregate_version = v_run.version - 1
    FOR SHARE;
    IF NOT FOUND OR v_head.reason_code <> 'RUN_STARTED'
       OR v_head.worker_job_id IS DISTINCT FROM p_job_id
       OR v_head.worker_lease_token IS DISTINCT FROM p_lease_token
       OR v_head.worker_fencing_token IS DISTINCT FROM p_job_fencing_token THEN
      RAISE EXCEPTION 'agent_run_claim_fence_changed'
        USING ERRCODE = '40001';
    END IF;
    v_proof := jsonb_build_object(
      'schemaVersion', 'agent-run-claim-proof.v1',
      'runId', v_run.id,
      'jobId', p_job_id,
      'leaseTokenSha256', encode(
        extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
        'hex'
      ),
      'fencingToken', p_job_fencing_token,
      'inputSnapshotSha256', btrim(v_run.input_snapshot_hash),
      'occurredAt', to_char(
        v_head.occurred_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    );
    v_proof_sha256 := encode(
      extensions.digest(ops.canonical_jsonb_v1(v_proof), 'sha256'), 'hex'
    );
    IF v_head.proof_sha256 <> v_proof_sha256 THEN
      RAISE EXCEPTION 'agent_run_claim_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_run.case_id, v_run.agent_type, v_run.objective,
      v_run.evidence_scope_ids, v_run.input_snapshot_hash, v_run.max_cost,
      v_run.version, v_run.run_contract_version, v_run.dataset_snapshot_id,
      v_head.receipt_id, v_head.receipt_sha256;
    RETURN;
  END IF;

  IF v_run.status <> 'QUEUED' OR v_run.control_state <> 'NONE'
     OR v_run.version <> 1 OR v_run.started_at IS NOT NULL
     OR v_run.deadline_at <= v_now THEN
    RAISE EXCEPTION 'agent_run_claim_fence_stale' USING ERRCODE = '40001';
  END IF;
  PERFORM 1
  FROM core.dataset_snapshots AS snapshot
  WHERE snapshot.id = v_run.dataset_snapshot_id
    AND snapshot.snapshot_sha256 = v_run.input_snapshot_hash
    AND snapshot.snapshot_kind = 'AGENT_CASE'
    AND snapshot.state = 'READY'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_claim_snapshot_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_proof := jsonb_build_object(
    'schemaVersion', 'agent-run-claim-proof.v1',
    'runId', v_run.id,
    'jobId', p_job_id,
    'leaseTokenSha256', encode(
      extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
      'hex'
    ),
    'fencingToken', p_job_fencing_token,
    'inputSnapshotSha256', btrim(v_run.input_snapshot_hash),
    'occurredAt', to_char(
      v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  v_proof_sha256 := encode(
    extensions.digest(ops.canonical_jsonb_v1(v_proof), 'sha256'), 'hex'
  );
  v_budget_set_sha256 := encode(
    extensions.digest(ops.canonical_jsonb_v1(jsonb_build_object(
      'maxMicrosKrw', v_run.max_micros_krw,
      'reservedMicrosKrw', v_run.reserved_micros_krw,
      'budgetReservationState', v_run.budget_reservation_state
    )), 'sha256'), 'hex'
  );
  SELECT appended.receipt_id, appended.receipt_sha256,
         appended.audit_event_id, appended.outbox_event_id
  INTO v_receipt_id, v_receipt_sha256, v_unused_audit, v_unused_outbox
  FROM ops.append_analysis_run_control_receipt_v2(
    v_run.id, v_run.version, NULL, NULL, 'RUNNING', 'ACTIVE',
    'LEASE_CLAIM', v_proof_sha256, 'RESERVED', v_budget_set_sha256,
    'RUN_STARTED', v_proof_sha256, NULL, NULL, p_job_id,
    p_lease_token, p_job_fencing_token, v_now
  ) AS appended;
  UPDATE ops.agent_runs AS run
  SET status = 'RUNNING', control_state = 'ACTIVE', started_at = v_now,
      version = run.version + 1, updated_at = v_now
  WHERE run.id = v_run.id AND run.version = v_run.version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_claim_fence_stale' USING ERRCODE = '40001';
  END IF;
  RETURN QUERY SELECT v_run.case_id, v_run.agent_type, v_run.objective,
    v_run.evidence_scope_ids, v_run.input_snapshot_hash, v_run.max_cost,
    v_run.version + 1, v_run.run_contract_version,
    v_run.dataset_snapshot_id, v_receipt_id, v_receipt_sha256;
END
$$;
ALTER FUNCTION ops.claim_agent_run_worker_v2(uuid,uuid,uuid,bigint)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.claim_agent_run_worker_v2(uuid,uuid,uuid,bigint)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.claim_agent_run_worker_v2(uuid,uuid,uuid,bigint)
  TO gurine_analysis_worker;

CREATE OR REPLACE FUNCTION ops.mark_agent_run_reconciliation_required_worker_v2(
  p_agent_run_id uuid,
  p_expected_version bigint,
  p_prior_receipt_id uuid,
  p_prior_receipt_sha256 char(64),
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint,
  p_ambiguity_proof jsonb,
  p_ambiguity_proof_sha256 char(64)
) RETURNS TABLE(
  version bigint,
  reconciliation_receipt_id uuid,
  reconciliation_receipt_sha256 char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, extensions, pg_temp
AS $$
DECLARE
  v_run ops.agent_runs%ROWTYPE;
  v_job ops.jobs%ROWTYPE;
  v_prior ops.agent_run_control_receipts%ROWTYPE;
  v_existing ops.agent_run_control_receipts%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_reason_binding jsonb;
  v_reason_sha256 char(64);
  v_budget_set_sha256 char(64);
  v_receipt_id uuid;
  v_receipt_sha256 char(64);
  v_unused_audit uuid;
  v_unused_outbox uuid;
BEGIN
  IF p_agent_run_id IS NULL OR p_expected_version IS NULL
     OR p_expected_version < 2 OR p_job_id IS NULL
     OR p_lease_token IS NULL OR p_job_fencing_token IS NULL
     OR p_job_fencing_token < 1
     OR p_prior_receipt_id IS NULL
     OR p_prior_receipt_sha256 IS NULL
     OR p_prior_receipt_sha256 !~ '^[0-9a-f]{64}$'
     OR p_ambiguity_proof IS NULL
     OR jsonb_typeof(p_ambiguity_proof) IS DISTINCT FROM 'object'
     OR p_ambiguity_proof_sha256 IS NULL
     OR p_ambiguity_proof_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'agent_run_ambiguity_request_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_ambiguity_proof)) <> 5
     OR NOT p_ambiguity_proof ?& ARRAY[
       'schemaVersion','runId','reasonCode','detailSha256','redacted'
     ]
     OR jsonb_typeof(p_ambiguity_proof->'schemaVersion')
       IS DISTINCT FROM 'string'
     OR p_ambiguity_proof->>'schemaVersion' IS DISTINCT FROM
       'agent-run-ambiguity-proof.v1'
     OR jsonb_typeof(p_ambiguity_proof->'runId') IS DISTINCT FROM 'string'
     OR p_ambiguity_proof->>'runId' IS DISTINCT FROM p_agent_run_id::text
     OR jsonb_typeof(p_ambiguity_proof->'reasonCode')
       IS DISTINCT FROM 'string'
     OR p_ambiguity_proof->>'reasonCode'
       IS DISTINCT FROM 'PROVIDER_OUTCOME_UNKNOWN'
     OR jsonb_typeof(p_ambiguity_proof->'detailSha256')
       IS DISTINCT FROM 'string'
     OR COALESCE(p_ambiguity_proof->>'detailSha256','')
       !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_ambiguity_proof->'redacted')
       IS DISTINCT FROM 'boolean'
     OR p_ambiguity_proof->'redacted' IS DISTINCT FROM 'true'::jsonb
     OR p_ambiguity_proof_sha256 IS DISTINCT FROM encode(
       extensions.digest(
         ops.canonical_jsonb_v1(p_ambiguity_proof), 'sha256'
       ), 'hex'
     ) THEN
    RAISE EXCEPTION 'agent_run_ambiguity_proof_invalid'
      USING ERRCODE = '22023';
  END IF;
  v_reason_binding := jsonb_build_object(
    'schemaVersion', 'agent-run-worker-transition-command.v1',
    'runId', p_agent_run_id,
    'expectedVersion', p_expected_version,
    'priorReceiptId', p_prior_receipt_id,
    'priorReceiptSha256', btrim(p_prior_receipt_sha256),
    'nextStatus', 'RUNNING',
    'nextControlState', 'RECONCILIATION_REQUIRED',
    'proofSha256', btrim(p_ambiguity_proof_sha256),
    'jobId', p_job_id,
    'leaseTokenSha256', encode(
      extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
      'hex'
    ),
    'fencingToken', p_job_fencing_token
  );
  v_reason_sha256 := encode(
    extensions.digest(
      ops.canonical_jsonb_v1(v_reason_binding), 'sha256'
    ), 'hex'
  );
  SELECT run.* INTO v_run
  FROM ops.agent_runs AS run
  WHERE run.id = p_agent_run_id
  FOR UPDATE;
  IF NOT FOUND OR v_run.run_contract_version <> 2 THEN
    RAISE EXCEPTION 'agent_run_v2_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_run.version = p_expected_version + 1
     AND v_run.status = 'RUNNING'
     AND v_run.control_state = 'RECONCILIATION_REQUIRED' THEN
    SELECT receipt.* INTO v_existing
    FROM ops.agent_run_control_receipts AS receipt
    WHERE receipt.agent_run_id = v_run.id
      AND receipt.aggregate_version = p_expected_version
    FOR SHARE;
    IF NOT FOUND OR v_existing.reason_code <> 'OUTCOME_AMBIGUOUS'
       OR v_existing.reason_sha256 <> v_reason_sha256
       OR v_existing.proof_sha256 <> p_ambiguity_proof_sha256
       OR v_existing.prior_receipt_id IS DISTINCT FROM p_prior_receipt_id
       OR v_existing.prior_receipt_sha256 IS DISTINCT FROM
         p_prior_receipt_sha256
       OR v_existing.worker_job_id IS DISTINCT FROM p_job_id
       OR v_existing.worker_lease_token IS DISTINCT FROM p_lease_token
       OR v_existing.worker_fencing_token IS DISTINCT FROM
         p_job_fencing_token THEN
      RAISE EXCEPTION 'agent_run_ambiguity_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_run.version, v_existing.receipt_id,
      v_existing.receipt_sha256, true;
    RETURN;
  END IF;
  IF v_run.version <> p_expected_version OR v_run.status <> 'RUNNING'
     OR v_run.control_state <> 'ACTIVE' THEN
    RAISE EXCEPTION 'agent_run_ambiguity_fence_stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT receipt.* INTO v_prior
  FROM ops.agent_run_control_receipts AS receipt
  WHERE receipt.agent_run_id = v_run.id
    AND receipt.aggregate_version = p_expected_version - 1
    AND receipt.receipt_id = p_prior_receipt_id
    AND receipt.receipt_sha256 = p_prior_receipt_sha256
  FOR SHARE;
  IF NOT FOUND OR v_prior.next_status <> v_run.status
     OR v_prior.next_control_state <> v_run.control_state THEN
    RAISE EXCEPTION 'agent_run_control_predecessor_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id AND job.job_type = 'AGENT_RUN'
    AND job.queue = 'analysis-worker' AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > v_now
    AND job.payload->>'agentRunId' = p_agent_run_id::text
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_job_fence_stale' USING ERRCODE = '40001';
  END IF;
  v_budget_set_sha256 := encode(
    extensions.digest(ops.canonical_jsonb_v1(jsonb_build_object(
      'reservedMicrosKrw', v_run.reserved_micros_krw,
      'settledMicrosKrw', v_run.settled_micros_krw,
      'budgetReservationState', 'RECONCILIATION_REQUIRED'
    )), 'sha256'), 'hex'
  );
  SELECT appended.receipt_id, appended.receipt_sha256,
         appended.audit_event_id, appended.outbox_event_id
  INTO v_receipt_id, v_receipt_sha256, v_unused_audit, v_unused_outbox
  FROM ops.append_analysis_run_control_receipt_v2(
    v_run.id, v_run.version, v_run.status, v_run.control_state,
    'RUNNING', 'RECONCILIATION_REQUIRED', 'COMMAND_INPUT',
    p_ambiguity_proof_sha256, 'RECONCILIATION_REQUIRED',
    v_budget_set_sha256, 'OUTCOME_AMBIGUOUS', v_reason_sha256,
    p_prior_receipt_id, p_prior_receipt_sha256, p_job_id,
    p_lease_token, p_job_fencing_token, v_now
  ) AS appended;
  UPDATE ops.agent_runs AS run
  SET control_state = 'RECONCILIATION_REQUIRED',
      budget_reservation_state = 'RECONCILIATION_REQUIRED',
      version = run.version + 1, updated_at = v_now
  WHERE run.id = v_run.id AND run.version = v_run.version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_ambiguity_fence_stale'
      USING ERRCODE = '40001';
  END IF;
  RETURN QUERY SELECT v_run.version + 1, v_receipt_id,
    v_receipt_sha256, false;
END
$$;
ALTER FUNCTION ops.mark_agent_run_reconciliation_required_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,jsonb,char(64)
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.mark_agent_run_reconciliation_required_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,jsonb,char(64)
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.mark_agent_run_reconciliation_required_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,jsonb,char(64)
) TO gurine_analysis_worker;

CREATE OR REPLACE FUNCTION ops.complete_agent_run_worker_v2(
  p_agent_run_id uuid,
  p_expected_version bigint,
  p_prior_receipt_id uuid,
  p_prior_receipt_sha256 char(64),
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint,
  p_next_status text,
  p_provider text,
  p_model text,
  p_output_payload jsonb,
  p_output_sha256 char(64),
  p_failure_code text,
  p_failure_proof jsonb,
  p_failure_proof_sha256 char(64),
  p_actual_cost numeric
) RETURNS TABLE(
  version bigint,
  terminal_receipt_id uuid,
  terminal_receipt_sha256 char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, ops, extensions, pg_temp
AS $$
DECLARE
  v_run ops.agent_runs%ROWTYPE;
  v_job ops.jobs%ROWTYPE;
  v_prior ops.agent_run_control_receipts%ROWTYPE;
  v_existing ops.agent_run_control_receipts%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_output_sha256 char(64);
  v_proof_sha256 char(64);
  v_proof_kind text;
  v_reason_code text;
  v_reason_binding jsonb;
  v_reason_sha256 char(64);
  v_budget_disposition text;
  v_budget_state text;
  v_budget_set_sha256 char(64);
  v_actual_micros_krw bigint;
  v_receipt_id uuid;
  v_receipt_sha256 char(64);
  v_unused_audit uuid;
  v_unused_outbox uuid;
BEGIN
  IF p_agent_run_id IS NULL OR p_expected_version IS NULL
     OR p_expected_version < 2
     OR p_prior_receipt_id IS NULL
     OR p_prior_receipt_sha256 IS NULL
     OR p_prior_receipt_sha256 !~ '^[0-9a-f]{64}$'
     OR p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token IS NULL OR p_job_fencing_token < 1
     OR p_next_status IS NULL
     OR p_next_status NOT IN (
       'SUCCEEDED','FAILED','BUDGET_BLOCKED','POLICY_BLOCKED'
     )
     OR p_actual_cost IS NULL OR p_actual_cost < 0
     OR scale(p_actual_cost) > 6 THEN
    RAISE EXCEPTION 'agent_run_terminal_request_invalid'
      USING ERRCODE = '22023';
  END IF;
  v_actual_micros_krw := round(p_actual_cost * 1000000)::bigint;
  IF p_next_status = 'FAILED' THEN
    IF p_provider IS NOT NULL OR p_model IS NOT NULL
       OR p_output_payload IS NOT NULL OR p_output_sha256 IS NOT NULL
       OR p_actual_cost <> 0
       OR p_failure_code IS NULL
       OR p_failure_code NOT IN (
         'OUTPUT_SCHEMA_INVALID','PROVIDER_UNAVAILABLE',
         'INTERNAL_EXECUTION_FAILED','CITATION_INVALID','RIGHTS_DENIED',
         'CLASSIFICATION_DENIED','ITERATION_LIMIT_REACHED',
         'CANCELLED_BY_USER','RECONCILIATION_FAILED'
       )
       OR p_failure_proof IS NULL
       OR jsonb_typeof(p_failure_proof) IS DISTINCT FROM 'object'
       OR p_failure_proof_sha256 IS NULL
       OR p_failure_proof_sha256 !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'agent_run_failure_shape_invalid'
        USING ERRCODE = '22023';
    END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(p_failure_proof)) <> 5
       OR NOT p_failure_proof ?& ARRAY[
         'schemaVersion','runId','failureCode','detailSha256','redacted'
       ]
       OR jsonb_typeof(p_failure_proof->'schemaVersion')
         IS DISTINCT FROM 'string'
       OR p_failure_proof->>'schemaVersion' IS DISTINCT FROM
         'agent-run-definitive-failure-proof.v1'
       OR jsonb_typeof(p_failure_proof->'runId') IS DISTINCT FROM 'string'
       OR p_failure_proof->>'runId' IS DISTINCT FROM p_agent_run_id::text
       OR jsonb_typeof(p_failure_proof->'failureCode')
         IS DISTINCT FROM 'string'
       OR p_failure_proof->>'failureCode' IS DISTINCT FROM p_failure_code
       OR jsonb_typeof(p_failure_proof->'detailSha256')
         IS DISTINCT FROM 'string'
       OR COALESCE(p_failure_proof->>'detailSha256','')
         !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(p_failure_proof->'redacted')
         IS DISTINCT FROM 'boolean'
       OR p_failure_proof->'redacted' IS DISTINCT FROM 'true'::jsonb
       OR p_failure_proof_sha256 IS DISTINCT FROM encode(
         extensions.digest(
           ops.canonical_jsonb_v1(p_failure_proof), 'sha256'
         ), 'hex'
       ) THEN
      RAISE EXCEPTION 'agent_run_failure_proof_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_proof_sha256 := p_failure_proof_sha256;
    v_proof_kind := 'DEFINITIVE_INTERNAL_FAILURE';
    v_reason_code := 'DEFINITIVE_FAILURE';
  ELSE
    IF nullif(btrim(p_provider), '') IS NULL
       OR nullif(btrim(p_model), '') IS NULL
       OR p_output_payload IS NULL
       OR p_output_sha256 IS NULL
       OR p_output_sha256 !~ '^[0-9a-f]{64}$'
       OR p_failure_code IS NOT NULL OR p_failure_proof IS NOT NULL
       OR p_failure_proof_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'agent_run_output_shape_invalid'
        USING ERRCODE = '22023';
    END IF;
    v_output_sha256 := encode(
      extensions.digest(
        ops.canonical_jsonb_v1(p_output_payload), 'sha256'
      ), 'hex'
    );
    IF p_output_sha256 <> v_output_sha256 THEN
      RAISE EXCEPTION 'agent_run_output_digest_mismatch'
        USING ERRCODE = '22023';
    END IF;
    v_proof_sha256 := p_output_sha256;
    v_proof_kind := CASE p_next_status
      WHEN 'SUCCEEDED' THEN 'VALIDATED_FINAL_OUTPUT'
      ELSE 'DEFINITIVE_NO_DISPATCH'
    END;
    v_reason_code := CASE p_next_status
      WHEN 'SUCCEEDED' THEN 'FINAL_OUTPUT_VALIDATED'
      WHEN 'BUDGET_BLOCKED' THEN 'BUDGET_DENIED'
      ELSE 'POLICY_DENIED'
    END;
  END IF;
  v_reason_binding := jsonb_build_object(
    'schemaVersion', 'agent-run-worker-transition-command.v1',
    'runId', p_agent_run_id,
    'expectedVersion', p_expected_version,
    'priorReceiptId', p_prior_receipt_id,
    'priorReceiptSha256', btrim(p_prior_receipt_sha256),
    'nextStatus', p_next_status,
    'nextControlState', 'SETTLED',
    'provider', p_provider,
    'model', p_model,
    'outputSha256', CASE
      WHEN p_output_sha256 IS NULL THEN NULL ELSE btrim(p_output_sha256)
    END,
    'failureCode', p_failure_code,
    'failureProofSha256', CASE WHEN p_failure_proof_sha256 IS NULL
      THEN NULL ELSE btrim(p_failure_proof_sha256) END,
    'actualCost', p_actual_cost::text,
    'jobId', p_job_id,
    'leaseTokenSha256', encode(
      extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
      'hex'
    ),
    'fencingToken', p_job_fencing_token
  );
  v_reason_sha256 := encode(
    extensions.digest(
      ops.canonical_jsonb_v1(v_reason_binding), 'sha256'
    ), 'hex'
  );
  SELECT run.* INTO v_run
  FROM ops.agent_runs AS run
  WHERE run.id = p_agent_run_id
  FOR UPDATE;
  IF NOT FOUND OR v_run.run_contract_version <> 2 THEN
    RAISE EXCEPTION 'agent_run_v2_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_actual_micros_krw > v_run.reserved_micros_krw
     OR v_actual_micros_krw > v_run.max_micros_krw THEN
    RAISE EXCEPTION 'agent_run_terminal_cost_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF v_run.version = p_expected_version + 1
     AND v_run.status = p_next_status
     AND v_run.control_state = 'SETTLED' THEN
    SELECT receipt.* INTO v_existing
    FROM ops.agent_run_control_receipts AS receipt
    WHERE receipt.agent_run_id = v_run.id
      AND receipt.aggregate_version = p_expected_version
    FOR SHARE;
    IF NOT FOUND OR v_existing.reason_sha256 <> v_reason_sha256
       OR v_existing.proof_sha256 <> v_proof_sha256
       OR v_existing.prior_receipt_id IS DISTINCT FROM p_prior_receipt_id
       OR v_existing.prior_receipt_sha256 IS DISTINCT FROM
         p_prior_receipt_sha256
       OR v_existing.worker_job_id IS DISTINCT FROM p_job_id
       OR v_existing.worker_lease_token IS DISTINCT FROM p_lease_token
       OR v_existing.worker_fencing_token IS DISTINCT FROM
         p_job_fencing_token
       OR v_run.provider IS DISTINCT FROM p_provider
       OR v_run.model IS DISTINCT FROM p_model
       OR v_run.output_payload IS DISTINCT FROM p_output_payload
       OR v_run.failure_code IS DISTINCT FROM p_failure_code
       OR v_run.actual_cost IS DISTINCT FROM p_actual_cost THEN
      RAISE EXCEPTION 'agent_run_terminal_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_run.version, v_existing.receipt_id,
      v_existing.receipt_sha256, true;
    RETURN;
  END IF;
  IF v_run.version <> p_expected_version OR v_run.status <> 'RUNNING'
     OR v_run.control_state <> 'ACTIVE' THEN
    RAISE EXCEPTION 'agent_run_terminal_fence_stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT receipt.* INTO v_prior
  FROM ops.agent_run_control_receipts AS receipt
  WHERE receipt.agent_run_id = v_run.id
    AND receipt.aggregate_version = p_expected_version - 1
    AND receipt.receipt_id = p_prior_receipt_id
    AND receipt.receipt_sha256 = p_prior_receipt_sha256
  FOR SHARE;
  IF NOT FOUND OR v_prior.next_status <> v_run.status
     OR v_prior.next_control_state <> v_run.control_state THEN
    RAISE EXCEPTION 'agent_run_control_predecessor_invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id AND job.job_type = 'AGENT_RUN'
    AND job.queue = 'analysis-worker' AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > v_now
    AND job.payload->>'agentRunId' = p_agent_run_id::text
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_job_fence_stale' USING ERRCODE = '40001';
  END IF;
  v_budget_disposition := CASE p_next_status
    WHEN 'BUDGET_BLOCKED' THEN 'RELEASED'
    WHEN 'POLICY_BLOCKED' THEN 'RELEASED'
    ELSE 'SETTLED'
  END;
  v_budget_state := v_budget_disposition;
  v_budget_set_sha256 := encode(
    extensions.digest(ops.canonical_jsonb_v1(jsonb_build_object(
      'maxMicrosKrw', v_run.max_micros_krw,
      'reservedMicrosKrw', v_run.reserved_micros_krw,
      'settledMicrosKrw', v_actual_micros_krw,
      'releasedMicrosKrw', v_run.reserved_micros_krw - v_actual_micros_krw,
      'budgetReservationState', v_budget_state
    )), 'sha256'), 'hex'
  );
  SELECT appended.receipt_id, appended.receipt_sha256,
         appended.audit_event_id, appended.outbox_event_id
  INTO v_receipt_id, v_receipt_sha256, v_unused_audit, v_unused_outbox
  FROM ops.append_analysis_run_control_receipt_v2(
    v_run.id, v_run.version, v_run.status, v_run.control_state,
    p_next_status, 'SETTLED', v_proof_kind, v_proof_sha256,
    v_budget_disposition, v_budget_set_sha256, v_reason_code,
    v_reason_sha256, p_prior_receipt_id, p_prior_receipt_sha256,
    p_job_id, p_lease_token, p_job_fencing_token, v_now
  ) AS appended;
  UPDATE ops.agent_runs AS run
  SET status = p_next_status, control_state = 'SETTLED',
      provider = p_provider, model = p_model,
      output_payload = p_output_payload,
      actual_cost = p_actual_cost,
      settled_micros_krw = v_actual_micros_krw,
      remaining_micros_krw = run.max_micros_krw - v_actual_micros_krw,
      budget_reservation_state = v_budget_state,
      failure_code = p_failure_code,
      terminal_receipt_sha256 = v_receipt_sha256,
      completed_at = v_now, version = run.version + 1, updated_at = v_now
  WHERE run.id = v_run.id AND run.version = v_run.version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run_terminal_fence_stale'
      USING ERRCODE = '40001';
  END IF;
  PERFORM ops.enqueue_outbox(
    'agent_run', v_run.id::text, v_run.version,
    'agent.run_completed.v1',
    jsonb_build_object(
      'agent_run_id', v_run.id,
      'case_id', v_run.case_id,
      'output_digest', btrim(v_proof_sha256),
      'status', p_next_status
    ), v_now
  );
  RETURN QUERY SELECT v_run.version + 1, v_receipt_id,
    v_receipt_sha256, false;
END
$$;
ALTER FUNCTION ops.complete_agent_run_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,text,text,text,jsonb,char(64),
  text,jsonb,char(64),numeric
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.complete_agent_run_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,text,text,text,jsonb,char(64),
  text,jsonb,char(64),numeric
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.complete_agent_run_worker_v2(
  uuid,bigint,uuid,char(64),uuid,uuid,bigint,text,text,text,jsonb,char(64),
  text,jsonb,char(64),numeric
) TO gurine_analysis_worker;

CREATE OR REPLACE FUNCTION core.complete_normalization_run(
  p_normalization_run_id uuid, p_expected_version bigint, p_job_id uuid,
  p_lease_token uuid, p_job_fencing_token bigint, p_terminal_state text,
  p_output_object_type text, p_output_object_id uuid,
  p_output_object_version bigint, p_output_payload_sha256 char(64),
  p_field_provenance_count bigint,
  p_field_provenance_set_sha256 char(64), p_error_code text,
  p_error_sha256 char(64)
) RETURNS TABLE(
  normalization_run_id uuid, state text, version bigint,
  terminal_receipt_sha256 char(64), audit_event_id uuid,
  outbox_event_id uuid, replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_run core.normalization_runs%ROWTYPE;
  v_job ops.jobs%ROWTYPE;
  v_audit ops.audit_events%ROWTYPE;
  v_outbox ops.outbox%ROWTYPE;
  v_completed_at timestamptz;
  v_lease_token_sha256 char(64);
  v_receipt jsonb;
  v_receipt_canonical bytea;
  v_receipt_sha256 char(64);
  v_audit_details jsonb;
  v_event_payload jsonb;
  v_audit_event_id uuid;
  v_outbox_event_id uuid;
  v_updated bigint;
BEGIN
  IF p_normalization_run_id IS NULL OR p_expected_version IS NULL
     OR p_expected_version < 1
     OR p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token IS NULL OR p_job_fencing_token < 1
     OR p_terminal_state IS NULL
     OR p_terminal_state NOT IN ('SUCCEEDED','FAILED')
     OR p_field_provenance_count IS NULL
     OR p_field_provenance_count < 0 THEN
    RAISE EXCEPTION 'invalid_normalization_completion'
      USING ERRCODE = '22023';
  END IF;
  IF p_terminal_state = 'SUCCEEDED' THEN
    IF p_output_object_type IS NULL OR p_output_object_type NOT IN (
         'AGENCY','SUPPLIER','CONTRACT','CONTRACT_LINE_ITEM',
         'CONTRACT_CHANGE','PRICE_OBSERVATION','PROCUREMENT_NOTICE',
         'PROCUREMENT_AWARD','PROCUREMENT_BIDDER_PARTICIPATION',
         'PROCUREMENT_CONTRACT','PROCUREMENT_CONTRACT_AMENDMENT',
         'PROCUREMENT_CONTRACT_LINE_ITEM','SUPPLIER_IDENTITY_CANDIDATE'
       ) OR p_output_object_id IS NULL
       OR p_output_object_version IS NULL OR p_output_object_version < 1
       OR p_output_payload_sha256 IS NULL
       OR p_output_payload_sha256 !~ '^[0-9a-f]{64}$'
       OR p_field_provenance_count < 1
       OR p_field_provenance_set_sha256 IS NULL
       OR p_field_provenance_set_sha256 !~ '^[0-9a-f]{64}$'
       OR p_error_code IS NOT NULL OR p_error_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'invalid_succeeded_normalization_shape'
        USING ERRCODE = '22023';
    END IF;
  ELSIF p_output_object_type IS NOT NULL OR p_output_object_id IS NOT NULL
     OR p_output_object_version IS NOT NULL
     OR p_output_payload_sha256 IS NOT NULL
     OR p_field_provenance_count <> 0
     OR p_field_provenance_set_sha256 IS NOT NULL
     OR p_error_code IS NULL
     OR p_error_code !~ '^[A-Z][A-Z0-9_]{0,127}$'
     OR p_error_sha256 IS NULL
     OR p_error_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid_failed_normalization_shape'
      USING ERRCODE = '22023';
  END IF;
  v_lease_token_sha256 := encode(
    extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
    'hex'
  );
  SELECT normalization.* INTO v_run
  FROM core.normalization_runs AS normalization
  WHERE normalization.id = p_normalization_run_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'normalization_run_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_run.job_id <> p_job_id
     OR v_run.job_fencing_token <> p_job_fencing_token THEN
    RAISE EXCEPTION 'normalization_completion_job_fence_mismatch'
      USING ERRCODE = '40001';
  END IF;
  v_completed_at := CASE WHEN v_run.state IN ('SUCCEEDED','FAILED')
    THEN v_run.completed_at ELSE clock_timestamp() END;
  v_receipt := jsonb_build_object(
    'schemaVersion','normalization-run-terminal-receipt.v1',
    'normalizationRunId',v_run.id,
    'sourceDocumentId',v_run.source_document_id,
    'parserRunId',v_run.parser_run_id,
    'parsedRecordId',v_run.parsed_record_id,
    'parserVersion',v_run.parser_version,
    'inputPayloadSha256',btrim(v_run.input_payload_sha256),
    'normalizationId',v_run.normalization_id,
    'normalizationVersion',v_run.normalization_version,
    'normalizationContractSha256',btrim(v_run.normalization_contract_sha256),
    'implementationSha256',btrim(v_run.implementation_sha256),
    'producerGeneration',v_run.producer_generation,
    'priorState','RUNNING','priorVersion',p_expected_version,
    'state',p_terminal_state,'aggregateVersion',p_expected_version + 1,
    'jobId',p_job_id,'jobFencingToken',p_job_fencing_token,
    'jobLeaseTokenSha256',btrim(v_lease_token_sha256),
    'outputObjectType',p_output_object_type,
    'outputObjectId',p_output_object_id,
    'outputObjectVersion',p_output_object_version,
    'outputPayloadSha256',CASE WHEN p_output_payload_sha256 IS NULL
      THEN NULL ELSE btrim(p_output_payload_sha256) END,
    'fieldProvenanceCount',p_field_provenance_count,
    'fieldProvenanceSetSha256',CASE
      WHEN p_field_provenance_set_sha256 IS NULL THEN NULL
      ELSE btrim(p_field_provenance_set_sha256) END,
    'errorCode',p_error_code,
    'errorSha256',CASE WHEN p_error_sha256 IS NULL
      THEN NULL ELSE btrim(p_error_sha256) END,
    'completedAt',to_char(
      v_completed_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  v_receipt_canonical := ops.canonical_jsonb_v1(v_receipt);
  v_receipt_sha256 := encode(
    extensions.digest(v_receipt_canonical, 'sha256'), 'hex'
  );
  v_audit_details := jsonb_build_object(
    'receipt',v_receipt,'terminalReceiptSha256',btrim(v_receipt_sha256)
  );
  v_event_payload := jsonb_build_object(
    'normalizationRunId',v_run.id,'state',p_terminal_state,
    'aggregateVersion',p_expected_version + 1,
    'outputObjectType',p_output_object_type,
    'outputObjectId',p_output_object_id,
    'outputObjectVersion',p_output_object_version,
    'outputPayloadSha256',CASE WHEN p_output_payload_sha256 IS NULL
      THEN NULL ELSE btrim(p_output_payload_sha256) END,
    'fieldProvenanceCount',p_field_provenance_count,
    'fieldProvenanceSetSha256',CASE
      WHEN p_field_provenance_set_sha256 IS NULL THEN NULL
      ELSE btrim(p_field_provenance_set_sha256) END,
    'errorCode',p_error_code,
    'errorSha256',CASE WHEN p_error_sha256 IS NULL
      THEN NULL ELSE btrim(p_error_sha256) END,
    'terminalReceiptSha256',btrim(v_receipt_sha256),
    'auditEventId',v_run.terminal_audit_event_id,
    'occurredAt',to_char(
      v_completed_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  IF v_run.state IN ('SUCCEEDED','FAILED') THEN
    IF v_run.version <> p_expected_version + 1
       OR v_run.state <> p_terminal_state
       OR v_run.output_object_type IS DISTINCT FROM p_output_object_type
       OR v_run.output_object_id IS DISTINCT FROM p_output_object_id
       OR v_run.output_object_version IS DISTINCT FROM p_output_object_version
       OR v_run.output_payload_sha256 IS DISTINCT FROM p_output_payload_sha256
       OR v_run.field_provenance_count <> p_field_provenance_count
       OR v_run.field_provenance_set_sha256 IS DISTINCT FROM
         p_field_provenance_set_sha256
       OR v_run.error_code IS DISTINCT FROM p_error_code
       OR v_run.error_sha256 IS DISTINCT FROM p_error_sha256
       OR v_run.terminal_receipt_sha256 IS DISTINCT FROM v_receipt_sha256
       OR v_run.terminal_audit_event_id IS NULL THEN
      RAISE EXCEPTION 'normalization_completion_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    SELECT audit.* INTO v_audit FROM ops.audit_events AS audit
    WHERE audit.id = v_run.terminal_audit_event_id;
    IF NOT FOUND OR v_audit.actor_type IS DISTINCT FROM 'SERVICE'
       OR v_audit.actor_id IS DISTINCT FROM 'ingest-worker'
       OR v_audit.action IS DISTINCT FROM (
         CASE p_terminal_state
           WHEN 'SUCCEEDED' THEN 'NORMALIZATION_RUN_SUCCEEDED'
           ELSE 'NORMALIZATION_RUN_FAILED'
         END
       )
       OR v_audit.object_type IS DISTINCT FROM 'NormalizationRun'
       OR v_audit.object_id IS DISTINCT FROM v_run.id::text
       OR v_audit.capability IS DISTINCT FROM 'jobs.operate'
       OR v_audit.outcome IS DISTINCT FROM (
         CASE p_terminal_state
           WHEN 'SUCCEEDED' THEN 'SUCCESS'::ops.audit_outcome
           ELSE 'FAILED'::ops.audit_outcome
         END
       )
       OR v_audit.reason IS DISTINCT FROM (
         CASE p_terminal_state WHEN 'FAILED' THEN p_error_code ELSE NULL END
       )
       OR v_audit.request_id IS DISTINCT FROM p_job_id
       OR v_audit.details IS DISTINCT FROM v_audit_details THEN
      RAISE EXCEPTION 'normalization_completion_replay_audit_conflict'
        USING ERRCODE = '40001';
    END IF;
    v_event_payload := jsonb_set(
      v_event_payload,'{auditEventId}',
      to_jsonb(v_run.terminal_audit_event_id),false
    );
    SELECT event.* INTO v_outbox FROM ops.outbox AS event
    WHERE event.aggregate_type = 'NormalizationRun'
      AND event.aggregate_id = v_run.id::text
      AND event.aggregate_version = v_run.version
      AND event.event_type = 'normalization.run_completed.v1';
    IF NOT FOUND OR v_outbox.payload IS DISTINCT FROM v_event_payload
       OR v_outbox.occurred_at IS DISTINCT FROM v_run.completed_at THEN
      RAISE EXCEPTION 'normalization_completion_replay_outbox_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_run.id,v_run.state,v_run.version,
      v_run.terminal_receipt_sha256,v_run.terminal_audit_event_id,
      v_outbox.id,true;
    RETURN;
  END IF;
  IF v_run.state <> 'RUNNING' OR v_run.version <> p_expected_version THEN
    RAISE EXCEPTION 'normalization_completion_version_stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT job.* INTO v_job FROM ops.jobs AS job
  WHERE job.id = p_job_id AND job.queue = 'ingest-worker'
    AND job.status = 'RUNNING' AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'normalization_completion_lease_stale'
      USING ERRCODE = '40001';
  END IF;
  v_audit_event_id := ops.append_audit_event(
    'normalization:' || v_run.id::text,'SERVICE','ingest-worker',NULL,
    CASE p_terminal_state WHEN 'SUCCEEDED' THEN 'NORMALIZATION_RUN_SUCCEEDED'
      ELSE 'NORMALIZATION_RUN_FAILED' END,
    'NormalizationRun',v_run.id::text,'jobs.operate',
    CASE p_terminal_state WHEN 'SUCCEEDED' THEN 'SUCCESS'::ops.audit_outcome
      ELSE 'FAILED'::ops.audit_outcome END,
    CASE p_terminal_state WHEN 'FAILED' THEN p_error_code ELSE NULL END,
    p_job_id,v_audit_details
  );
  UPDATE core.normalization_runs AS normalization
  SET state=p_terminal_state,output_object_type=p_output_object_type,
      output_object_id=p_output_object_id,
      output_object_version=p_output_object_version,
      output_payload_sha256=p_output_payload_sha256,
      field_provenance_count=p_field_provenance_count,
      field_provenance_set_sha256=p_field_provenance_set_sha256,
      error_code=p_error_code,error_sha256=p_error_sha256,
      terminal_receipt_sha256=v_receipt_sha256,
      terminal_audit_event_id=v_audit_event_id,
      version=normalization.version + 1,completed_at=v_completed_at
  WHERE normalization.id=p_normalization_run_id
    AND normalization.state='RUNNING'
    AND normalization.version=p_expected_version
    AND normalization.job_id=p_job_id
    AND normalization.job_fencing_token=p_job_fencing_token;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RAISE EXCEPTION 'normalization_completion_transition_lost'
      USING ERRCODE = '40001';
  END IF;
  v_event_payload := jsonb_set(
    v_event_payload,'{auditEventId}',to_jsonb(v_audit_event_id),false
  );
  v_outbox_event_id := ops.enqueue_outbox(
    'NormalizationRun',v_run.id::text,p_expected_version + 1,
    'normalization.run_completed.v1',v_event_payload,v_completed_at
  );
  RETURN QUERY SELECT v_run.id,p_terminal_state,p_expected_version + 1,
    v_receipt_sha256,v_audit_event_id,v_outbox_event_id,false;
END
$$;
ALTER FUNCTION core.complete_normalization_run(
  uuid,bigint,uuid,uuid,bigint,text,text,uuid,bigint,char(64),bigint,
  char(64),text,char(64)
) OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.complete_normalization_run(
  uuid,bigint,uuid,uuid,bigint,text,text,uuid,bigint,char(64),bigint,
  char(64),text,char(64)
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.complete_normalization_run(
  uuid,bigint,uuid,uuid,bigint,text,text,uuid,bigint,char(64),bigint,
  char(64),text,char(64)
) TO gurine_ingest_worker;

GRANT SELECT ON core.contracts, core.contract_changes, core.rule_versions,
  raw.source_documents, core.suppliers TO gurine_migrator;
GRANT UPDATE (id) ON core.contracts, core.rule_versions,
  raw.source_documents, core.supplier_identifiers TO gurine_migrator;

CREATE OR REPLACE FUNCTION core.current_detection_contract_identity_v1()
RETURNS TABLE(
  contract_count bigint,
  contract_identity_list jsonb,
  contract_identity_canonical bytea,
  contract_identity_set_sha256 char(64)
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_count bigint;
  v_list jsonb;
  v_canonical bytea;
BEGIN
  PERFORM contract.id
  FROM core.contracts AS contract
  JOIN raw.source_documents AS document
    ON document.id = contract.source_document_id
  ORDER BY contract.id::text, contract.version, contract.updated_at
  FOR SHARE OF contract, document;
  SELECT count(*)::bigint,
         COALESCE(jsonb_agg(jsonb_build_object(
           'id', contract.id,
           'version', contract.version,
           'updatedAt', to_char(
             contract.updated_at AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
           )
         ) ORDER BY contract.id::text, contract.version,
                    contract.updated_at), '[]'::jsonb)
  INTO v_count, v_list
  FROM core.contracts AS contract
  JOIN raw.source_documents AS document
    ON document.id = contract.source_document_id;
  v_canonical := ops.canonical_jsonb_v1(v_list);
  RETURN QUERY SELECT v_count, v_list, v_canonical,
    encode(extensions.digest(v_canonical, 'sha256'), 'hex')::char(64);
END
$$;
ALTER FUNCTION core.current_detection_contract_identity_v1()
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION core.current_detection_contract_identity_v1()
  FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.enqueue_due_detection_snapshot_builds_v1(
  p_limit bigint
) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_identity record;
  v_rule record;
  v_inserted bigint := 0;
  v_changed bigint;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
    RAISE EXCEPTION 'detection_snapshot_sweep_limit_invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_identity
  FROM core.current_detection_contract_identity_v1();
  FOR v_rule IN
    SELECT version.id, version.rule_id
    FROM core.rule_versions AS version
    WHERE version.status = 'ACTIVE'
      AND NOT EXISTS (
        SELECT 1
        FROM ops.jobs AS existing_job
        WHERE existing_job.dedupe_key =
          'detection-snapshot-build:' || version.id::text || ':' ||
          btrim(v_identity.contract_identity_set_sha256)
      )
    ORDER BY version.rule_id, version.id
    LIMIT p_limit
  LOOP
    INSERT INTO ops.jobs(
      job_type, queue, payload, dedupe_key, max_attempts
    ) VALUES (
      'DETECTION_SNAPSHOT_BUILD', 'analysis-worker',
      jsonb_build_object(
        'schemaVersion', 'detection-snapshot-build-job.v1',
        'ruleVersionId', v_rule.id,
        'ruleId', v_rule.rule_id,
        'contractIdentitySetSha256',
          btrim(v_identity.contract_identity_set_sha256),
        'contractCount', v_identity.contract_count
      ),
      'detection-snapshot-build:' || v_rule.id::text || ':' ||
        btrim(v_identity.contract_identity_set_sha256),
      8
    ) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_changed = ROW_COUNT;
    v_inserted := v_inserted + v_changed;
  END LOOP;
  RETURN v_inserted;
END
$$;
ALTER FUNCTION ops.enqueue_due_detection_snapshot_builds_v1(bigint)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION ops.enqueue_due_detection_snapshot_builds_v1(bigint)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.enqueue_due_detection_snapshot_builds_v1(bigint)
  TO gurine_scheduler;

CREATE OR REPLACE FUNCTION core.build_detection_dataset_snapshot_v1(
  p_job_id uuid,
  p_lease_token uuid,
  p_job_fencing_token bigint
) RETURNS TABLE(
  snapshot_id uuid,
  snapshot_sha256 char(64),
  member_count bigint,
  strong_identifier_fact_count bigint,
  strong_identifier_fact_set_sha256 char(64),
  replayed boolean
)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, raw, core, ops, extensions, pg_temp
AS $$
DECLARE
  v_job ops.jobs%ROWTYPE;
  v_rule core.rule_versions%ROWTYPE;
  v_identity record;
  v_existing core.dataset_snapshots%ROWTYPE;
  v_existing_count bigint;
  v_rule_configuration_sha256 char(64);
  v_producer_key text;
  v_producer_canonical bytea;
  v_producer_digest char(64);
  v_selection jsonb;
  v_selection_canonical bytea;
  v_source_watermarks jsonb;
  v_source_watermarks_canonical bytea;
  v_initial_normalization_versions jsonb;
  v_initial_normalization_canonical bytea;
  v_normalization_versions jsonb;
  v_normalization_canonical bytea;
  v_normalization_set_sha256 char(64);
  v_snapshot_id uuid := gen_random_uuid();
  v_build_request jsonb;
  v_build_request_sha256 char(64);
  v_build_started_audit_event_id uuid;
  v_begin record;
  v_contract record;
  v_member_id uuid;
  v_contract_content jsonb;
  v_object_content_sha256 char(64);
  v_payload jsonb;
  v_payload_canonical bytea;
  v_payload_sha256 char(64);
  v_source_canonical bytea;
  v_source_digest char(64);
  v_source_set_sha256 char(64);
  v_member_binding_canonical bytea;
  v_member_digest char(64);
  v_member_count bigint := 0;
  v_member_digests jsonb := '[]'::jsonb;
  v_member_set_sha256 char(64);
  v_fact record;
  v_fact_canonical bytea;
  v_fact_digest char(64);
  v_fact_count bigint := 0;
  v_fact_digests jsonb := '[]'::jsonb;
  v_fact_set_sha256 char(64);
  v_snapshot_manifest jsonb;
  v_snapshot_manifest_canonical bytea;
  v_snapshot_sha256 char(64);
  v_terminal_at timestamptz;
  v_terminal_receipt jsonb;
  v_terminal_receipt_canonical bytea;
  v_terminal_receipt_sha256 char(64);
  v_terminal_audit_event_id uuid;
  v_final record;
  v_updated integer;
BEGIN
  IF p_job_id IS NULL OR p_lease_token IS NULL
     OR p_job_fencing_token IS NULL OR p_job_fencing_token < 1 THEN
    RAISE EXCEPTION 'detection_snapshot_build_fence_invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT job.* INTO v_job
  FROM ops.jobs AS job
  WHERE job.id = p_job_id
    AND job.job_type = 'DETECTION_SNAPSHOT_BUILD'
    AND job.queue = 'analysis-worker'
    AND job.status = 'RUNNING'
    AND job.lease_token = p_lease_token
    AND job.fencing_token = p_job_fencing_token
    AND job.lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'detection_snapshot_build_lease_stale'
      USING ERRCODE = '40001';
  END IF;
  IF jsonb_typeof(v_job.payload) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(v_job.payload)) <> 5
     OR NOT v_job.payload ?& ARRAY[
       'schemaVersion','ruleVersionId','ruleId',
       'contractIdentitySetSha256','contractCount'
     ]
     OR jsonb_typeof(v_job.payload->'schemaVersion') <> 'string'
     OR v_job.payload->>'schemaVersion' <>
       'detection-snapshot-build-job.v1'
     OR jsonb_typeof(v_job.payload->'ruleVersionId') <> 'string'
     OR jsonb_typeof(v_job.payload->'ruleId') <> 'string'
     OR nullif(btrim(v_job.payload->>'ruleId'), '') IS NULL
     OR btrim(v_job.payload->>'ruleId') <> v_job.payload->>'ruleId'
     OR jsonb_typeof(v_job.payload->'contractIdentitySetSha256') <> 'string'
     OR v_job.payload->>'contractIdentitySetSha256' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_job.payload->'contractCount') <> 'number'
     OR v_job.payload->>'contractCount' !~ '^(0|[1-9][0-9]*)$' THEN
    RAISE EXCEPTION 'detection_snapshot_build_payload_invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT version.* INTO v_rule
  FROM core.rule_versions AS version
  WHERE version.id::text = v_job.payload->>'ruleVersionId'
  FOR SHARE;
  IF NOT FOUND OR v_rule.status <> 'ACTIVE'
     OR v_rule.rule_id <> v_job.payload->>'ruleId'
     OR v_rule.code_digest !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'detection_snapshot_build_rule_authority_invalid'
      USING ERRCODE = '55000';
  END IF;
  v_rule_configuration_sha256 := encode(
    extensions.digest(
      ops.canonical_jsonb_v1(v_rule.configuration), 'sha256'
    ), 'hex'
  );
  v_producer_key := 'detection-rule:' || v_rule.id::text;
  v_producer_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
    'schemaVersion','r6b-detection-snapshot-producer.v1',
    'ruleId',v_rule.rule_id,
    'ruleVersionId',v_rule.id,
    'ruleCodeSha256',btrim(v_rule.code_digest),
    'ruleConfigurationSha256',btrim(v_rule_configuration_sha256)
  ));
  v_producer_digest := encode(
    extensions.digest(v_producer_canonical, 'sha256'), 'hex'
  );
  SELECT count(*) INTO v_existing_count
  FROM core.dataset_snapshots AS snapshot
  WHERE snapshot.producer_job_id = p_job_id;
  IF v_existing_count > 1 THEN
    RAISE EXCEPTION 'detection_snapshot_build_replay_cardinality_invalid'
      USING ERRCODE = '40001';
  ELSIF v_existing_count = 1 THEN
    SELECT snapshot.* INTO STRICT v_existing
    FROM core.dataset_snapshots AS snapshot
    WHERE snapshot.producer_job_id = p_job_id
    FOR UPDATE;
    SELECT count(*), encode(extensions.digest(
      ops.canonical_jsonb_v1(COALESCE(jsonb_agg(
        btrim(fact.fact_digest) ORDER BY fact.fact_ordinal
      ),'[]'::jsonb)), 'sha256'
    ), 'hex')
    INTO v_fact_count, v_fact_set_sha256
    FROM core.dataset_snapshot_strong_identifier_facts AS fact
    WHERE fact.dataset_snapshot_id = v_existing.id;
    v_normalization_versions := jsonb_build_object(
      'schemaVersion','dataset-normalization-versions.v1',
      'entries','[]'::jsonb,
      'detectionDatasetAuthority',jsonb_build_object(
        'schemaVersion','r6b-detection-dataset-authority.v1',
        'contractIdentitySetSha256',
          v_job.payload->>'contractIdentitySetSha256',
        'contractCount',(v_job.payload->>'contractCount')::bigint,
        'strongIdentifierFactCount',v_fact_count,
        'strongIdentifierFactSetSha256',btrim(v_fact_set_sha256)
      )
    );
    IF v_existing.state <> 'READY'
       OR v_existing.snapshot_kind <> 'DETECTION_DATASET'
       OR v_existing.producer_key <> v_producer_key
       OR v_existing.producer_digest <> v_producer_digest
       OR (SELECT count(*) FROM jsonb_object_keys(v_existing.selection_spec))
         <> 7
       OR v_existing.selection_spec->>'snapshotKind' <>
         'DETECTION_DATASET'
       OR v_existing.selection_spec->>'ruleId' <> v_rule.rule_id
       OR v_existing.selection_spec->>'ruleVersionId' <> v_rule.id::text
       OR v_existing.selection_spec->>'ruleCodeSha256' <>
         btrim(v_rule.code_digest)
       OR v_existing.selection_spec->>'ruleConfigurationSha256' <>
         btrim(v_rule_configuration_sha256)
       OR jsonb_typeof(v_existing.selection_spec->'cohortSpec') <> 'array'
       OR nullif(
         v_existing.selection_spec->>'selectionPolicyVersion',''
       ) IS NULL
       OR v_existing.normalization_versions <> v_normalization_versions
       OR v_existing.strong_identifier_fact_count <> v_fact_count
       OR v_existing.strong_identifier_fact_set_sha256 <> v_fact_set_sha256
       OR v_existing.member_count <> (
         SELECT count(*) FROM core.dataset_snapshot_members AS member
         WHERE member.dataset_snapshot_id = v_existing.id
       )
       OR EXISTS (
         SELECT 1
         FROM core.dataset_snapshot_members AS member
         WHERE member.dataset_snapshot_id = v_existing.id
           AND (
             member.object_type <> 'CONTRACT'
             OR member.source_count <> 1
             OR (
               SELECT count(*)
               FROM core.dataset_snapshot_member_sources AS source
               WHERE source.snapshot_member_id = member.id
                 AND source.lineage_kind = 'DIRECT_SOURCE'
                 AND source.source_kind = 'SOURCE_DOCUMENT'
             ) <> 1
           )
       )
       OR v_existing.snapshot_sha256 <> encode(
         extensions.digest(v_existing.snapshot_manifest_canonical,'sha256'),
         'hex'
       ) THEN
      RAISE EXCEPTION 'detection_snapshot_build_replay_conflict'
        USING ERRCODE = '40001';
    END IF;
    RETURN QUERY SELECT v_existing.id,v_existing.snapshot_sha256,
      v_existing.member_count,v_fact_count,v_fact_set_sha256,true;
    RETURN;
  END IF;
  SELECT * INTO STRICT v_identity
  FROM core.current_detection_contract_identity_v1();
  IF v_identity.contract_count <> (v_job.payload->>'contractCount')::bigint
     OR btrim(v_identity.contract_identity_set_sha256) <>
       v_job.payload->>'contractIdentitySetSha256'
     OR v_job.dedupe_key IS DISTINCT FROM
       'detection-snapshot-build:' || v_rule.id::text || ':' ||
       btrim(v_identity.contract_identity_set_sha256) THEN
    RAISE EXCEPTION 'detection_snapshot_build_contract_identity_stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'objectType','CONTRACT','objectId',contract.id,
    'objectVersion',contract.version
  ) ORDER BY contract.id::text,contract.version,contract.updated_at),'[]'::jsonb)
  INTO v_selection
  FROM core.contracts AS contract;
  v_selection := jsonb_build_object(
    'snapshotKind','DETECTION_DATASET',
    'ruleId',v_rule.rule_id,
    'ruleVersionId',v_rule.id,
    'ruleCodeSha256',btrim(v_rule.code_digest),
    'ruleConfigurationSha256',btrim(v_rule_configuration_sha256),
    'cohortSpec',v_selection,
    'selectionPolicyVersion','detection-contract-identity-v1'
  );
  v_selection_canonical := ops.canonical_jsonb_v1(v_selection);
  v_source_watermarks := jsonb_build_object(
    'schemaVersion','dataset-source-watermarks.v1',
    'eventFence',0,
    'checkpoints','[]'::jsonb
  );
  v_source_watermarks_canonical :=
    ops.canonical_jsonb_v1(v_source_watermarks);
  v_initial_normalization_versions := jsonb_build_object(
    'schemaVersion','dataset-normalization-versions.v1',
    'entries','[]'::jsonb
  );
  v_initial_normalization_canonical :=
    ops.canonical_jsonb_v1(v_initial_normalization_versions);
  v_build_request := jsonb_build_object(
    'schemaVersion','detection-snapshot-build-request.v1',
    'snapshotId',v_snapshot_id,
    'jobId',p_job_id,
    'jobPayload',v_job.payload,
    'producerKey',v_producer_key,
    'producerDigest',btrim(v_producer_digest),
    'selectionSha256',encode(
      extensions.digest(v_selection_canonical,'sha256'),'hex'
    ),
    'contractIdentitySetSha256',
      btrim(v_identity.contract_identity_set_sha256),
    'contractCount',v_identity.contract_count
  );
  v_build_request_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_build_request),'sha256'
  ),'hex');
  v_build_started_audit_event_id := ops.append_audit_event(
    'snapshot:' || v_snapshot_id::text,'SERVICE','analysis-worker',NULL,
    'DATASET_SNAPSHOT_BUILD_STARTED','DatasetSnapshot',
    v_snapshot_id::text,'jobs.operate','SUCCESS',NULL,p_job_id,
    jsonb_build_object(
      'snapshotId',v_snapshot_id,
      'snapshotKind','DETECTION_DATASET',
      'producerJobId',p_job_id,
      'buildRequestSha256',btrim(v_build_request_sha256),
      'ruleId',v_rule.rule_id,
      'ruleVersionId',v_rule.id,
      'contractIdentitySetSha256',
        btrim(v_identity.contract_identity_set_sha256),
      'contractCount',v_identity.contract_count
    )
  );
  SELECT * INTO STRICT v_begin
  FROM core.begin_dataset_snapshot(
    'DETECTION_DATASET',p_job_id,v_producer_key,v_producer_digest,
    'dataset-snapshot.v1',v_selection,v_selection_canonical,
    v_source_watermarks,v_source_watermarks_canonical,
    v_initial_normalization_versions,v_initial_normalization_canonical,
    v_build_request_sha256,v_build_started_audit_event_id
  );
  IF v_begin.snapshot_id <> v_snapshot_id OR v_begin.reused
     OR v_begin.state <> 'BUILDING' OR v_begin.producer_generation < 1 THEN
    RAISE EXCEPTION 'detection_snapshot_build_begin_conflict'
      USING ERRCODE = '40001';
  END IF;

  FOR v_contract IN
    SELECT contract.*,document.asset_id,document.asset_revision,
      document.content_sha256 AS source_content_sha256,
      count(change.id)::bigint AS amendment_count,
      CASE WHEN count(change.id) = 0 THEN false
        ELSE bool_and(nullif(btrim(change.reason),'') IS NOT NULL)
      END AS scope_change_explained
    FROM core.contracts AS contract
    JOIN raw.source_documents AS document
      ON document.id = contract.source_document_id
    LEFT JOIN core.contract_changes AS change
      ON change.contract_id = contract.id
    GROUP BY contract.id,document.id
    ORDER BY contract.id::text,contract.version,contract.updated_at
  LOOP
    v_member_id := gen_random_uuid();
    v_contract_content := jsonb_build_object(
      'schemaVersion','contract-snapshot.v1',
      'objectType','CONTRACT',
      'objectId',v_contract.id,
      'objectVersion',v_contract.version,
      'objectSchemaVersion','contract-snapshot.v1',
      'externalContractId',v_contract.external_contract_id,
      'title',v_contract.title,
      'agencyId',v_contract.agency_id,
      'supplierId',v_contract.supplier_id,
      'status',v_contract.status::text,
      'currency',btrim(v_contract.currency),
      'procurementMethod',v_contract.procurement_method,
      'signedAt',CASE WHEN v_contract.signed_at IS NULL THEN NULL
        ELSE to_char(v_contract.signed_at,'YYYY-MM-DD') END,
      'startAt',CASE WHEN v_contract.start_at IS NULL THEN NULL
        ELSE to_char(v_contract.start_at,'YYYY-MM-DD') END,
      'endAt',CASE WHEN v_contract.end_at IS NULL THEN NULL
        ELSE to_char(v_contract.end_at,'YYYY-MM-DD') END,
      'originalAmount',v_contract.original_amount,
      'currentAmount',v_contract.current_amount,
      'vatBasis',v_contract.vat_basis,
      'bundleStatus',v_contract.bundle_status,
      'normalizationVersion',v_contract.normalization_version,
      'sourceDocumentId',v_contract.source_document_id,
      'sourceRecordLocator',v_contract.source_record_locator,
      'updatedAt',to_char(
        v_contract.updated_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'amendmentCount',v_contract.amendment_count,
      'scopeChangeExplained',v_contract.scope_change_explained
    );
    v_object_content_sha256 := encode(extensions.digest(
      ops.canonical_jsonb_v1(v_contract_content),'sha256'
    ),'hex');
    v_payload := v_contract_content || jsonb_build_object(
      'objectContentSha256',btrim(v_object_content_sha256)
    );
    v_payload_canonical := ops.canonical_jsonb_v1(v_payload);
    v_payload_sha256 := encode(
      extensions.digest(v_payload_canonical,'sha256'),'hex'
    );
    v_source_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
      'schemaVersion','dataset-snapshot-member-source.v1',
      'snapshotId',v_snapshot_id,
      'snapshotMemberId',v_member_id,
      'memberOrdinal',v_member_count,
      'sourceOrdinal',0,
      'lineageKind','DIRECT_SOURCE',
      'sourceKind','SOURCE_DOCUMENT',
      'sourceDocumentId',v_contract.source_document_id,
      'sourceAssetId',v_contract.asset_id,
      'sourceAssetRevision',v_contract.asset_revision,
      'sourceContentSha256',btrim(v_contract.source_content_sha256)
    ));
    v_source_digest := encode(
      extensions.digest(v_source_canonical,'sha256'),'hex'
    );
    v_source_set_sha256 := encode(extensions.digest(
      ops.canonical_jsonb_v1(jsonb_build_array(btrim(v_source_digest))),
      'sha256'
    ),'hex');
    v_member_binding_canonical := ops.canonical_jsonb_v1(
      jsonb_build_object(
        'schemaVersion','dataset-snapshot-member-binding.v1',
        'snapshotId',v_snapshot_id,
        'snapshotMemberId',v_member_id,
        'snapshotKind','DETECTION_DATASET',
        'producerGeneration',v_begin.producer_generation,
        'snapshotContractVersion',1,
        'memberOrdinal',v_member_count,
        'objectType','CONTRACT',
        'objectId',v_contract.id,
        'objectVersion',v_contract.version,
        'objectSchemaVersion','contract-snapshot.v1',
        'objectContentSha256',btrim(v_object_content_sha256),
        'payloadSha256',btrim(v_payload_sha256),
        'normalizationRunId',NULL,
        'normalizationVersion',NULL,
        'normalizationSha256',NULL,
        'evidenceSegmentId',NULL,
        'responseId',NULL,
        'sourceCount',1,
        'sourceSetSha256',btrim(v_source_set_sha256)
      )
    );
    v_member_digest := encode(extensions.digest(
      v_member_binding_canonical,'sha256'
    ),'hex');
    INSERT INTO core.dataset_snapshot_members(
      id,dataset_snapshot_id,snapshot_kind,producer_generation,
      snapshot_contract_version,member_ordinal,object_type,object_id,
      object_version,object_schema_version,object_content_sha256,
      canonical_payload,canonical_payload_bytes,payload_sha256,
      normalization_run_id,normalization_version,normalization_sha256,
      evidence_segment_id,response_id,source_count,source_set_sha256,
      member_binding_canonical,member_digest
    ) VALUES (
      v_member_id,v_snapshot_id,'DETECTION_DATASET',
      v_begin.producer_generation,1,v_member_count,'CONTRACT',v_contract.id,
      v_contract.version,'contract-snapshot.v1',v_object_content_sha256,
      v_payload,v_payload_canonical,v_payload_sha256,NULL,NULL,NULL,
      NULL,NULL,1,v_source_set_sha256,v_member_binding_canonical,
      v_member_digest
    );
    INSERT INTO core.dataset_snapshot_member_sources(
      dataset_snapshot_id,snapshot_member_id,member_ordinal,
      snapshot_member_digest,source_ordinal,lineage_kind,source_kind,
      source_document_id,source_asset_id,source_asset_revision,
      source_content_sha256,response_id,response_version,
      response_content_sha256,parser_run_id,parsed_record_id,
      normalization_run_id,field_provenance_id,evidence_segment_id,
      locator_digest,source_digest
    ) VALUES (
      v_snapshot_id,v_member_id,v_member_count,v_member_digest,0,
      'DIRECT_SOURCE','SOURCE_DOCUMENT',v_contract.source_document_id,
      v_contract.asset_id,v_contract.asset_revision,
      v_contract.source_content_sha256,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
      NULL,NULL,v_source_digest
    );
    v_member_digests := v_member_digests ||
      jsonb_build_array(btrim(v_member_digest));
    v_member_count := v_member_count + 1;
  END LOOP;

  FOR v_fact IN
    WITH ranked AS (
      SELECT
        member.id AS snapshot_member_id,
        member.member_digest AS snapshot_member_digest,
        member.object_version AS snapshot_member_object_version,
        member.object_content_sha256 AS snapshot_member_content_sha256,
        member.object_id AS contract_id,
        identifier.id AS identifier_id,
        identifier.supplier_id,
        identifier.scheme,
        identifier.value_hash,
        identifier.verification_status,
        identifier.proof_state,
        identifier.candidate_id,
        identifier.candidate_revision,
        identifier.candidate_digest,
        identifier.source_locator_digest,
        identifier.verification_evidence_digest,
        identifier.identifier_fact_digest,
        row_number() OVER (
          PARTITION BY identifier.id
          ORDER BY member.object_id::text,member.object_version,
            member.member_ordinal
        ) AS contract_rank
      FROM core.supplier_identifiers AS identifier
      JOIN core.dataset_snapshot_members AS member
        ON member.dataset_snapshot_id = v_snapshot_id
       AND member.object_type = 'CONTRACT'
       AND member.canonical_payload->>'supplierId' =
         identifier.supplier_id::text
      WHERE identifier.verification_status = 'VERIFIED'
        AND identifier.proof_state = 'PROVEN_V1'
        AND identifier.scheme IN (
          'KOREAN_BUSINESS_NUMBER','OPEN_DART_CORP_CODE','KONEPS_PARTY_KEY'
        )
    )
    SELECT *
    FROM ranked
    WHERE contract_rank = 1
    ORDER BY supplier_id::text,scheme,btrim(value_hash),identifier_id::text
  LOOP
    v_fact_canonical := ops.canonical_jsonb_v1(jsonb_build_object(
      'schemaVersion','dataset-snapshot-strong-identifier-fact.v1',
      'snapshotId',v_snapshot_id,
      'snapshotMemberId',v_fact.snapshot_member_id,
      'snapshotMemberDigest',btrim(v_fact.snapshot_member_digest),
      'snapshotMemberObjectType','CONTRACT',
      'snapshotMemberObjectVersion',v_fact.snapshot_member_object_version,
      'snapshotMemberObjectContentSha256',
        btrim(v_fact.snapshot_member_content_sha256),
      'contractId',v_fact.contract_id,
      'factOrdinal',v_fact_count,
      'supplierId',v_fact.supplier_id,
      'identifierId',v_fact.identifier_id,
      'scheme',v_fact.scheme,
      'valueHash',btrim(v_fact.value_hash),
      'verificationStatus',v_fact.verification_status,
      'proofState',v_fact.proof_state,
      'candidateId',v_fact.candidate_id,
      'candidateRevision',v_fact.candidate_revision,
      'candidateDigest',btrim(v_fact.candidate_digest),
      'sourceLocatorDigest',btrim(v_fact.source_locator_digest),
      'verificationEvidenceDigest',
        btrim(v_fact.verification_evidence_digest),
      'identifierFactDigest',btrim(v_fact.identifier_fact_digest)
    ));
    v_fact_digest := encode(
      extensions.digest(v_fact_canonical,'sha256'),'hex'
    );
    INSERT INTO core.dataset_snapshot_strong_identifier_facts(
      dataset_snapshot_id,snapshot_member_id,snapshot_member_digest,
      snapshot_member_object_type,snapshot_member_object_version,
      snapshot_member_object_content_sha256,contract_id,fact_ordinal,
      supplier_id,identifier_id,scheme,value_hash,verification_status,
      proof_state,candidate_id,candidate_revision,candidate_digest,
      source_locator_digest,verification_evidence_digest,
      identifier_fact_digest,fact_canonical,fact_digest
    ) VALUES (
      v_snapshot_id,v_fact.snapshot_member_id,
      v_fact.snapshot_member_digest,'CONTRACT',
      v_fact.snapshot_member_object_version,
      v_fact.snapshot_member_content_sha256,v_fact.contract_id,v_fact_count,
      v_fact.supplier_id,v_fact.identifier_id,v_fact.scheme,
      v_fact.value_hash,v_fact.verification_status,v_fact.proof_state,
      v_fact.candidate_id,v_fact.candidate_revision,v_fact.candidate_digest,
      v_fact.source_locator_digest,v_fact.verification_evidence_digest,
      v_fact.identifier_fact_digest,v_fact_canonical,v_fact_digest
    );
    v_fact_digests := v_fact_digests ||
      jsonb_build_array(btrim(v_fact_digest));
    v_fact_count := v_fact_count + 1;
  END LOOP;

  v_member_set_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_member_digests),'sha256'
  ),'hex');
  v_fact_set_sha256 := encode(extensions.digest(
    ops.canonical_jsonb_v1(v_fact_digests),'sha256'
  ),'hex');
  v_normalization_versions := jsonb_build_object(
    'schemaVersion','dataset-normalization-versions.v1',
    'entries','[]'::jsonb,
    'detectionDatasetAuthority',jsonb_build_object(
      'schemaVersion','r6b-detection-dataset-authority.v1',
      'contractIdentitySetSha256',
        btrim(v_identity.contract_identity_set_sha256),
      'contractCount',v_identity.contract_count,
      'strongIdentifierFactCount',v_fact_count,
      'strongIdentifierFactSetSha256',btrim(v_fact_set_sha256)
    )
  );
  v_normalization_canonical :=
    ops.canonical_jsonb_v1(v_normalization_versions);
  v_normalization_set_sha256 := encode(extensions.digest(
    v_normalization_canonical,'sha256'
  ),'hex');
  UPDATE core.dataset_snapshots AS snapshot
  SET normalization_versions = v_normalization_versions,
      normalization_versions_canonical = v_normalization_canonical,
      normalization_set_sha256 = v_normalization_set_sha256,
      strong_identifier_fact_count = v_fact_count,
      strong_identifier_fact_set_sha256 = v_fact_set_sha256
  WHERE snapshot.id = v_snapshot_id
    AND snapshot.state = 'BUILDING'
    AND snapshot.version = 1
    AND snapshot.normalization_versions = v_initial_normalization_versions;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RAISE EXCEPTION 'detection_snapshot_build_header_fence_lost'
      USING ERRCODE = '40001';
  END IF;
  v_snapshot_manifest := jsonb_build_object(
    'schemaVersion','dataset-snapshot-manifest.v1',
    'snapshotId',v_snapshot_id,
    'snapshotKind','DETECTION_DATASET',
    'producerDigest',btrim(v_producer_digest),
    'producerGeneration',v_begin.producer_generation,
    'selectionSha256',encode(
      extensions.digest(v_selection_canonical,'sha256'),'hex'
    ),
    'sourceWatermarkSha256',encode(
      extensions.digest(v_source_watermarks_canonical,'sha256'),'hex'
    ),
    'normalizationSetSha256',btrim(v_normalization_set_sha256),
    'memberCount',v_member_count,
    'memberSetSha256',btrim(v_member_set_sha256)
  );
  v_snapshot_manifest_canonical :=
    ops.canonical_jsonb_v1(v_snapshot_manifest);
  v_snapshot_sha256 := encode(extensions.digest(
    v_snapshot_manifest_canonical,'sha256'
  ),'hex');
  v_terminal_at := clock_timestamp();
  v_terminal_receipt := jsonb_build_object(
    'schemaVersion','dataset-snapshot-terminal-receipt.v1',
    'snapshotId',v_snapshot_id,
    'state','READY',
    'aggregateVersion',2,
    'snapshotSha256',btrim(v_snapshot_sha256),
    'memberCount',v_member_count,
    'memberSetSha256',btrim(v_member_set_sha256),
    'strongIdentifierFactCount',v_fact_count,
    'strongIdentifierFactSetSha256',btrim(v_fact_set_sha256),
    'occurredAt',to_char(
      v_terminal_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
  v_terminal_receipt_canonical :=
    ops.canonical_jsonb_v1(v_terminal_receipt);
  v_terminal_receipt_sha256 := encode(extensions.digest(
    v_terminal_receipt_canonical,'sha256'
  ),'hex');
  v_terminal_audit_event_id := ops.append_audit_event(
    'snapshot:' || v_snapshot_id::text,'SERVICE','analysis-worker',NULL,
    'DATASET_SNAPSHOT_READY','DatasetSnapshot',v_snapshot_id::text,
    'jobs.operate','SUCCESS',NULL,p_job_id,jsonb_build_object(
      'snapshotId',v_snapshot_id,
      'state','READY',
      'terminalReceiptDigest',btrim(v_terminal_receipt_sha256),
      'snapshotSha256',btrim(v_snapshot_sha256),
      'memberCount',v_member_count,
      'strongIdentifierFactCount',v_fact_count,
      'strongIdentifierFactSetSha256',btrim(v_fact_set_sha256)
    )
  );
  SELECT * INTO STRICT v_final
  FROM core.finalize_dataset_snapshot(
    v_snapshot_id,1,'READY',v_member_count,v_member_set_sha256,
    v_snapshot_manifest,v_snapshot_manifest_canonical,
    v_terminal_receipt_sha256,v_terminal_audit_event_id,NULL,NULL
  );
  IF v_final.snapshot_id <> v_snapshot_id OR v_final.state <> 'READY'
     OR v_final.version <> 2
     OR v_final.snapshot_sha256 <> v_snapshot_sha256
     OR v_final.member_count <> v_member_count THEN
    RAISE EXCEPTION 'detection_snapshot_build_finalization_conflict'
      USING ERRCODE = '40001';
  END IF;
  RETURN QUERY SELECT v_snapshot_id,v_snapshot_sha256,v_member_count,
    v_fact_count,v_fact_set_sha256,false;
END
$$;
ALTER FUNCTION core.build_detection_dataset_snapshot_v1(uuid,uuid,bigint)
  OWNER TO gurine_migrator;
REVOKE ALL ON FUNCTION
  core.build_detection_dataset_snapshot_v1(uuid,uuid,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION
  core.build_detection_dataset_snapshot_v1(uuid,uuid,bigint)
  TO gurine_analysis_worker;

REVOKE INSERT, UPDATE, DELETE ON core.dataset_snapshots,
  core.dataset_snapshot_members,core.dataset_snapshot_member_sources
  FROM gurine_analysis_worker;
REVOKE EXECUTE ON FUNCTION core.begin_dataset_snapshot(
  text,uuid,text,char(64),text,jsonb,bytea,jsonb,bytea,jsonb,bytea,
  char(64),uuid
) FROM gurine_analysis_worker;
REVOKE EXECUTE ON FUNCTION core.finalize_dataset_snapshot(
  uuid,bigint,text,bigint,char(64),jsonb,bytea,char(64),uuid,text,char(64)
) FROM gurine_analysis_worker;
